/**
 * @module features/tv-dashboard/model/useTvDashboardData
 *
 * Hook principal da Torre de Controle da Operação (painel TV `/tv`).
 *
 * Paraleliza as fontes de dados via React Query:
 * - vendas live (edge `degust-pos-financial`/flash-vendas) — polling 60s;
 * - vendas defasadas Linx (`historico_vendas`, último dia disponível);
 * - comparativos: vs DIA ANTERIOR (principal, v3 — base pró-rateada p/ canal
 *   live) e vs MESMO DIA da semana passada (secundário);
 * - metas por loja × dia da semana (`metas_vendas`) com pró-rata da janela;
 * - alertas de estoque NOMEADOS (`estoque` × `produtos_master.ativo = true`,
 *   restritos ao setor de produtos vendáveis — `TV_ALERT_SETOR`);
 * - heartbeat + FEED nomeado de movimentações (`movimentacoes` de hoje);
 * - perdas no período do filtro global (`perdas`, R$ + itens + delta);
 * - compras no período (`notas_fiscais`, "gasto até hoje" + delta);
 * - produção da fábrica (`daily_production` com loja_id NULL).
 *
 * Nenhum `loja_id` é hardcoded: os canais são derivados em runtime de
 * `lojas` + `degust_stores` (Degust = live; demais lojas ativas = Linx
 * defasado; tipo "Fabrica" = card de fábrica).
 */

import { useMemo } from 'react';
import { useQuery } from '@tanstack/react-query';
import { supabase } from '@/integrations/supabase/client';
import type {
  TvDateRange,
  TvDeliverySplit,
  TvException,
  TvFactoryData,
  TvFactoryProduction,
  TvFreshness,
  TvHourlyCurve,
  TvMarketingSummary,
  TvMetaMensal,
  TvMonthProgress,
  TvMovementSummary,
  TvNetworkSummary,
  TvPerdasSummary,
  TvPeriod,
  TvRecentMove,
  TvSalesChannel,
  TvSalesSnapshot,
  TvStoreData,
  TvStoreWeeklyGoal,
  TvExceptionsResult,
} from './types';
import {
  FACTORY_NO_MOVEMENT_THRESHOLD_HOURS,
  TV_BUSINESS_HOURS,
  TV_DELIVERY_SPLIT_LOJA_ID,
  TV_FACTORY_HOURS,
  TV_MINI_FEED_SIZE,
  addDays,
  businessTodayIso,
  aggregateMarketing,
  aggregateMovements,
  aggregatePerdas,
  businessDayFraction,
  buildFreshness,
  buildNoMovementException,
  buildRecentMoves,
  buildStockExceptions,
  buildStockSummary,
  classifyStoreRag,
  currentWeekGoal,
  fetchAllPages,
  hourlyPaceBase,
  monthEndProjection,
  parseDegustFlashDateTime,
  parseIsoDateLocal,
  pctOfFullDayTarget,
  pctOfProRataTarget,
  previousPeriodRange,
  proRataDayBase,
  rangeToLocalDayBounds,
  relativeDelta,
  remapFlashLojaIds,
  shiftedPeriodRange,
  sortAndLimitExceptions,
  sortCriticalItems,
  toIsoDateLocal,
  weekOverWeekDelta,
  weeklyTargets,
  type FlashRow,
  type MarketingAggregate,
  type MarketingByLoja,
  type MovementAggregate,
  type MovementFeedRow,
  type PerdasAggregate,
  type PerdasByLoja,
  type StockDetail,
  type StockRow,
} from './tvMath';
import { useMinuteClock } from './useMinuteClock';

// ─────────────────────────────────────────────────────────────────────────────
// Query keys + intervalos (exportados para o useTvRealtime invalidar)
// ─────────────────────────────────────────────────────────────────────────────

/** Query keys do painel TV — usar SEMPRE estas referências para invalidar. */
export const tvDashboardKeys = {
  all: ['tv-dashboard'] as const,
  context: () => [...tvDashboardKeys.all, 'context'] as const,
  liveSales: () => [...tvDashboardKeys.all, 'live-sales'] as const,
  laggedSales: () => [...tvDashboardKeys.all, 'lagged-sales'] as const,
  /** Vendas de referência Degust (ontem + mesmo dia da semana passada). */
  referenceSales: () => [...tvDashboardKeys.all, 'reference-sales'] as const,
  /** Vendas oficiais de um range PASSADO (modo histórico, `offset < 0`). */
  rangeSales: (range: TvDateRange, previousRange: TvDateRange) =>
    [
      ...tvDashboardKeys.all,
      'range-sales',
      range.from,
      range.to,
      previousRange.from,
    ] as const,
  /** Acumulado do mês corrente (01 → hoje) via ticket-medio. */
  mtdSales: () => [...tvDashboardKeys.all, 'mtd-sales'] as const,
  /** Curvas horárias ontem+hoje (delta vs ontem hora a hora). */
  hourlyCurves: () => [...tvDashboardKeys.all, 'hourly-curves'] as const,
  /** Quebra delivery×balcão (BSB Shopping) da data exibida. */
  deliverySplit: (date: string) =>
    [...tvDashboardKeys.all, 'delivery-split', date] as const,
  /** Metas mensais (`metas_mensais`) do mês corrente. */
  metasMensais: () => [...tvDashboardKeys.all, 'metas-mensais'] as const,
  metas: () => [...tvDashboardKeys.all, 'metas'] as const,
  stock: () => [...tvDashboardKeys.all, 'stock'] as const,
  movements: () => [...tvDashboardKeys.all, 'movements'] as const,
  /** Feed nomeado de movimentações de hoje (mini-feed "AGORA"). */
  movementFeed: () => [...tvDashboardKeys.all, 'movement-feed'] as const,
  /** Prefixo das perdas (invalidar TODOS os períodos/offsets de uma vez). */
  perdasRoot: () => [...tvDashboardKeys.all, 'perdas'] as const,
  perdas: (period: TvPeriod, offset = 0) =>
    [...tvDashboardKeys.perdasRoot(), period, offset] as const,
  /** Prefixo do marketing (invalidar TODOS os períodos/offsets de uma vez). */
  marketingRoot: () => [...tvDashboardKeys.all, 'marketing'] as const,
  marketing: (period: TvPeriod, offset = 0) =>
    [...tvDashboardKeys.marketingRoot(), period, offset] as const,
  factoryProduction: () => [...tvDashboardKeys.all, 'factory-production'] as const,
  /** Snapshot do relatório matinal (R6) por dia-base (`useTvReport`). */
  report: (date: string) => [...tvDashboardKeys.all, 'report', date] as const,
  /** Prefixo do drill-down por loja (invalidar todas as lojas/ranges). */
  storeDetailRoot: () => [...tvDashboardKeys.all, 'store-detail'] as const,
  storeDetail: (lojaId: number, range: TvDateRange) =>
    [...tvDashboardKeys.storeDetailRoot(), lojaId, range.from, range.to] as const,
};

/** Intervalos de atualização (ms) por classe de dado. */
export const TV_QUERY_INTERVALS = {
  /** Vendas live: polling 60s (acceptance: atualização em até 60s). */
  liveMs: 60_000,
  /** Estoque/metas/movimentações/produção: 5min (+ Realtime invalida antes). */
  slowMs: 300_000,
} as const;

/**
 * Duração da janela comercial em horas (deriva de {@link TV_BUSINESS_HOURS}
 * — hoje 8h–23h = 15h). Base do R$/hora e vendas/hora do hero.
 */
const TV_BUSINESS_WINDOW_HOURS = TV_BUSINESS_HOURS.end - TV_BUSINESS_HOURS.start;

// ─────────────────────────────────────────────────────────────────────────────
// Contexto: lojas + canais (derivados em runtime, sem hardcode de loja_id)
// ─────────────────────────────────────────────────────────────────────────────

/** Loja ativa carregada no contexto do painel. */
export interface TvLoja {
  id: number;
  nome: string;
  tipo: string | null;
}

/** Contexto runtime do painel (lojas + canais) — reusado pelo drill-down. */
export interface TvContext {
  lojas: TvLoja[];
  /** Lojas com venda live (existem em `degust_stores`). */
  degustLojaIds: Set<number>;
  /** Mapa código Degust → loja_id (corrige pass-through da edge function). */
  degustCodeToLoja: Map<number, number>;
  /** Lojas ativas de venda SEM integração live (canal Linx, defasado). */
  linxLojaIds: number[];
  /** Loja tipo fábrica (tipo "Fabrica", case-insensitive), ou null. */
  factoryLojaId: number | null;
}

function isFactoryTipo(tipo: string | null): boolean {
  // Valores reais na tabela divergem em caixa ("Fabrica" / "loja" / "Loja")
  return (tipo ?? '').toLowerCase().startsWith('fabrica') || (tipo ?? '').toLowerCase().startsWith('fábrica');
}

/** Carrega o contexto (exportado para o `useTvStoreDetail` compartilhar cache). */
export async function fetchTvContext(): Promise<TvContext> {
  const [lojasRes, degustRes] = await Promise.all([
    supabase
      .from('lojas')
      .select('id, nome, tipo')
      .eq('ativo', true)
      .order('id'),
    supabase.from('degust_stores').select('loja_id, degust_loja_codigo'),
  ]);
  if (lojasRes.error) throw lojasRes.error;
  if (degustRes.error) throw degustRes.error;

  const lojas: TvLoja[] = lojasRes.data ?? [];
  const degustLojaIds = new Set<number>();
  const degustCodeToLoja = new Map<number, number>();
  for (const row of degustRes.data ?? []) {
    degustLojaIds.add(row.loja_id);
    degustCodeToLoja.set(row.degust_loja_codigo, row.loja_id);
  }

  const factoryLojaId = lojas.find((l) => isFactoryTipo(l.tipo))?.id ?? null;
  const linxLojaIds = lojas
    .filter((l) => !isFactoryTipo(l.tipo) && !degustLojaIds.has(l.id))
    .map((l) => l.id);

  return { lojas, degustLojaIds, degustCodeToLoja, linxLojaIds, factoryLojaId };
}

// ─────────────────────────────────────────────────────────────────────────────
// Vendas live (edge degust-pos-financial / flash-vendas)
// ─────────────────────────────────────────────────────────────────────────────

/** Contrato da edge `degust-pos-financial` (campos usados pelo painel). */
interface DegustPosFinancialResponse {
  flash?: Array<{
    loja_id: number;
    nome_loja: string;
    total_vendas: number;
    total_cupons: number;
    ticket_medio: number;
    qtd_produtos: number;
    caixa_aberto: boolean;
    ultima_atualizacao: string | null;
  }>;
  /** Breakdown diário via ticket-medio (inclui ontem quando `startDate < endDate`). */
  daily?: Array<{
    data: string;       // YYYY-MM-DD
    loja_id: number;    // já remapeado pelo edge para loja_id interno
    total_faturado: number;
    total_cupons: number;
  }>;
  /** Modo includeDeliverySplit: cupons delivery por data (loja BSB). */
  deliverySplit?: Array<{
    data: string;
    loja_id: number;
    total_delivery: number;
    cupons_delivery: number;
  }>;
  /** Modo includeHourly: curva horária por loja × data. */
  hourly?: Array<{
    loja_id: number;
    data: string;
    byHour: Record<string, number>;
  }>;
}

/** Corpo aceito pela edge `degust-pos-financial` (campos usados aqui). */
interface DegustPosFinancialBody {
  startDate: string;
  endDate: string;
  includeDeliverySplit?: boolean;
  deliveryLojaId?: number;
  includeHourly?: boolean;
  hourlyDates?: string[];
}

/** Chamada única à edge `degust-pos-financial` (todos os fetchers Degust). */
async function callDegustEdge(
  body: DegustPosFinancialBody,
): Promise<DegustPosFinancialResponse> {
  const supabaseUrl = import.meta.env.VITE_SUPABASE_URL as string;
  const anonKey = import.meta.env.VITE_SUPABASE_PUBLISHABLE_KEY as string;
  const session = (await supabase.auth.getSession()).data.session;
  const token = session?.access_token ?? anonKey;

  const resp = await fetch(`${supabaseUrl}/functions/v1/degust-pos-financial`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      Authorization: `Bearer ${token}`,
      apikey: anonKey,
    },
    body: JSON.stringify(body),
  });

  if (!resp.ok) {
    throw new Error(`[tv-dashboard] degust-pos-financial: HTTP ${resp.status}`);
  }
  return (await resp.json()) as DegustPosFinancialResponse;
}

/**
 * Retorno de fetchLiveSales:
 * - flash: dados ao vivo de hoje (ou último caixa fechado se madrugada)
 * - dailyByLoja: mapa loja_id → data → total_faturado (3 dias)
 *   Permite detectar a data real do flash e comparar vs dia anterior correto.
 */
interface LiveSalesResult {
  flash: FlashRow[];
  dailyByLoja: Map<number, Map<string, number>>;
}

async function fetchLiveSales(ctx: TvContext): Promise<LiveSalesResult> {
  // Dia COMERCIAL (virada às 23h): após as 23h o painel já é o dia seguinte.
  const today = businessTodayIso(new Date());
  // Pedir 3 dias para cobrir a virada do dia comercial:
  // - hoje comercial (pode estar vazio se o dia acabou de virar/zerar);
  // - véspera (base do delta vs ontem);
  // - antevéspera (base quando o flash ainda é do dia recém-fechado).
  const twoDaysAgo = toIsoDateLocal(addDays(parseIsoDateLocal(today), -2));

  const data = await callDegustEdge({ startDate: twoDaysAgo, endDate: today });

  const flash: FlashRow[] = remapFlashLojaIds(
    (data?.flash ?? []).map((f) => ({
      loja_id: f.loja_id,
      nome_loja: f.nome_loja,
      total_vendas: f.total_vendas,
      total_cupons: f.total_cupons,
      ticket_medio: f.ticket_medio,
      caixa_aberto: f.caixa_aberto,
      ultima_atualizacao: f.ultima_atualizacao,
    })),
    ctx.degustCodeToLoja,
    ctx.degustLojaIds,
  );

  // Mapa loja_id → data → total via ticket-medio (dados completos por dia).
  // edge function v20 já remapeia codigoLoja → loja_id interno.
  const dailyByLoja = new Map<number, Map<string, number>>();
  for (const d of data?.daily ?? []) {
    if (!ctx.degustLojaIds.has(d.loja_id)) continue;
    let byDate = dailyByLoja.get(d.loja_id);
    if (!byDate) { byDate = new Map<string, number>(); dailyByLoja.set(d.loja_id, byDate); }
    byDate.set(d.data, (byDate.get(d.data) ?? 0) + (d.total_faturado ?? 0));
  }

  return { flash, dailyByLoja };
}

// ─────────────────────────────────────────────────────────────────────────────
// Modo histórico (offset < 0): vendas oficiais de um range passado (R2)
// ─────────────────────────────────────────────────────────────────────────────

/** Vendas oficiais (ticket-medio) por loja × data de um range PASSADO. */
interface RangeSalesResult {
  /** loja_id → data → R$ total oficial do dia. */
  dailyByLoja: Map<number, Map<string, number>>;
  /** loja_id → data → cupons do dia. */
  cuponsByLoja: Map<number, Map<string, number>>;
}

/**
 * Busca os totais oficiais por dia para o modo passado, numa ÚNICA chamada
 * cobrindo `[from, to]` — o caller passa `previousRange.from → range.to`
 * (ranges equivalentes consecutivos são contíguos por construção).
 */
async function fetchRangeSales(
  ctx: TvContext,
  from: string,
  to: string,
): Promise<RangeSalesResult> {
  const data = await callDegustEdge({ startDate: from, endDate: to });
  const dailyByLoja = new Map<number, Map<string, number>>();
  const cuponsByLoja = new Map<number, Map<string, number>>();
  for (const d of data.daily ?? []) {
    if (!ctx.degustLojaIds.has(d.loja_id)) continue;
    let valores = dailyByLoja.get(d.loja_id);
    if (!valores) {
      valores = new Map<string, number>();
      dailyByLoja.set(d.loja_id, valores);
    }
    valores.set(d.data, (valores.get(d.data) ?? 0) + (d.total_faturado ?? 0));
    let cupons = cuponsByLoja.get(d.loja_id);
    if (!cupons) {
      cupons = new Map<string, number>();
      cuponsByLoja.set(d.loja_id, cupons);
    }
    cupons.set(d.data, (cupons.get(d.data) ?? 0) + (d.total_cupons ?? 0));
  }
  return { dailyByLoja, cuponsByLoja };
}

/**
 * Soma os valores de um mapa data→R$ dentro de um range fechado [from, to].
 * `daysWithData` distingue "vendeu R$ 0" de "sem dado nenhum" (vendas null).
 */
function sumRange(
  byDate: Map<string, number> | undefined,
  range: TvDateRange,
): { total: number; daysWithData: number } {
  if (!byDate) return { total: 0, daysWithData: 0 };
  let total = 0;
  let daysWithData = 0;
  let d = parseIsoDateLocal(range.from);
  const end = parseIsoDateLocal(range.to).getTime();
  while (d.getTime() <= end) {
    const v = byDate.get(toIsoDateLocal(d));
    if (v != null) {
      total += v;
      daysWithData += 1;
    }
    d = addDays(d, 1);
  }
  return { total, daysWithData };
}

/** Dias FECHADOS de um range [from, to] (DST-safe via Math.round). */
function rangeDayCount(range: TvDateRange): number {
  const from = parseIsoDateLocal(range.from).getTime();
  const to = parseIsoDateLocal(range.to).getTime();
  return Math.round((to - from) / 86_400_000) + 1;
}

// ─────────────────────────────────────────────────────────────────────────────
// Acumulado do mês (R3): 01 → hoje via ticket-medio
// ─────────────────────────────────────────────────────────────────────────────

/** MTD da rede: total por DATA (rede) + total por LOJA + diário por LOJA. */
interface MtdSalesResult {
  /** data (YYYY-MM-DD) → R$ da REDE no dia (lojas Degust somadas). */
  byDate: Map<string, number>;
  /** loja_id → R$ acumulado no mês. */
  byLoja: Map<number, number>;
  /**
   * loja_id → data → R$ oficial do dia (01 → hoje). Base do `weeklyGoal`
   * por loja — MESMA passada de agregação do `byDate` da rede, sem fetch
   * adicional.
   */
  dailyByLoja: Map<number, Map<string, number>>;
}

async function fetchMtdSales(ctx: TvContext): Promise<MtdSalesResult> {
  const now = new Date();
  const from = toIsoDateLocal(new Date(now.getFullYear(), now.getMonth(), 1));
  const to = toIsoDateLocal(now);
  const data = await callDegustEdge({ startDate: from, endDate: to });
  const byDate = new Map<string, number>();
  const byLoja = new Map<number, number>();
  const dailyByLoja = new Map<number, Map<string, number>>();
  for (const d of data.daily ?? []) {
    if (!ctx.degustLojaIds.has(d.loja_id)) continue;
    const valor = d.total_faturado ?? 0;
    byDate.set(d.data, (byDate.get(d.data) ?? 0) + valor);
    byLoja.set(d.loja_id, (byLoja.get(d.loja_id) ?? 0) + valor);
    let porDia = dailyByLoja.get(d.loja_id);
    if (!porDia) {
      porDia = new Map<string, number>();
      dailyByLoja.set(d.loja_id, porDia);
    }
    porDia.set(d.data, (porDia.get(d.data) ?? 0) + valor);
  }
  return { byDate, byLoja, dailyByLoja };
}

// ─────────────────────────────────────────────────────────────────────────────
// Curvas horárias ontem+hoje (R5) e quebra delivery (R1)
// ─────────────────────────────────────────────────────────────────────────────

async function fetchHourlyCurves(): Promise<TvHourlyCurve[]> {
  // Dia COMERCIAL (virada às 23h): a curva de "ontem" precisa ser a do dia
  // recém-fechado — não a do dia-calendário — para o delta paceado.
  const today = businessTodayIso(new Date());
  const yesterday = toIsoDateLocal(addDays(parseIsoDateLocal(today), -1));
  const data = await callDegustEdge({
    startDate: yesterday,
    endDate: today,
    includeHourly: true,
    hourlyDates: [yesterday, today],
  });
  return (data.hourly ?? []).map((h) => ({
    lojaId: h.loja_id,
    data: h.data,
    byHour: h.byHour,
  }));
}

/**
 * Quebra delivery×balcão de UM dia (a data exibida: hoje no live, dia
 * selecionado no modo passado). null quando o dia não tem cupom delivery.
 */
async function fetchDeliverySplitDay(date: string): Promise<TvDeliverySplit | null> {
  const data = await callDegustEdge({
    startDate: date,
    endDate: date,
    includeDeliverySplit: true,
    deliveryLojaId: TV_DELIVERY_SPLIT_LOJA_ID,
  });
  const row = (data.deliverySplit ?? []).find((r) => r.data === date);
  if (!row) return null;
  return {
    lojaId: row.loja_id,
    data: row.data,
    totalDelivery: row.total_delivery,
    cuponsDelivery: row.cupons_delivery,
  };
}

// ─────────────────────────────────────────────────────────────────────────────
// Metas mensais (R4): `metas_mensais` do mês corrente
// ─────────────────────────────────────────────────────────────────────────────

async function fetchMetasMensais(now: Date): Promise<TvMetaMensal[]> {
  const { data, error } = await supabase
    .from('metas_mensais')
    .select('loja_id, ano, mes, valor_meta')
    .eq('ano', now.getFullYear())
    .eq('mes', now.getMonth() + 1);
  if (error) {
    // Tolerar ambiente onde a migration ainda não rodou (tabela ausente):
    // painel segue sem meta mensal em vez de derrubar o snapshot inteiro.
    console.error('[tv-dashboard] metas_mensais indisponível:', error.message);
    return [];
  }
  return (data ?? []).map((row) => ({
    lojaId: row.loja_id,
    ano: row.ano,
    mes: row.mes,
    valorMeta: row.valor_meta,
  }));
}

// ─────────────────────────────────────────────────────────────────────────────
// Vendas defasadas (Linx via historico_vendas — último dia disponível)
// ─────────────────────────────────────────────────────────────────────────────

interface LaggedSales {
  lojaId: number;
  /** Último dia com venda registrada (YYYY-MM-DD). */
  dataReferencia: string;
  valor: number;
  quantidade: number;
  /** Valor do MESMO DIA da semana anterior ao dia de referência, ou null. */
  valorSemanaAnterior: number | null;
  /** Valor do DIA ANTERIOR ao dia de referência (dias completos), ou null. */
  valorDiaAnterior: number | null;
}

async function fetchLaggedStore(lojaId: number): Promise<LaggedSales | null> {
  // 1) Último dia com dado para a loja
  const { data: latest, error: latestErr } = await supabase
    .from('historico_vendas')
    .select('data')
    .eq('loja_id', lojaId)
    .order('data', { ascending: false })
    .limit(1);
  if (latestErr) throw latestErr;
  const refDate = latest?.[0]?.data;
  if (!refDate) return null;

  const weekAgoDate = toIsoDateLocal(addDays(parseIsoDateLocal(refDate), -7));
  const dayBeforeDate = toIsoDateLocal(addDays(parseIsoDateLocal(refDate), -1));

  // 2) Vendas do dia de referência + bases de comparação (dia anterior =
  //    comparativo PRINCIPAL v3; mesma semana = secundário)
  const [curRes, weekRes, dayRes] = await Promise.all([
    supabase
      .from('historico_vendas')
      .select('valor_total, quantidade')
      .eq('loja_id', lojaId)
      .eq('data', refDate)
      .limit(2000),
    supabase
      .from('historico_vendas')
      .select('valor_total')
      .eq('loja_id', lojaId)
      .eq('data', weekAgoDate)
      .limit(2000),
    supabase
      .from('historico_vendas')
      .select('valor_total')
      .eq('loja_id', lojaId)
      .eq('data', dayBeforeDate)
      .limit(2000),
  ]);
  if (curRes.error) throw curRes.error;
  if (weekRes.error) throw weekRes.error;
  if (dayRes.error) throw dayRes.error;

  const valor = (curRes.data ?? []).reduce((s, r) => s + (r.valor_total ?? 0), 0);
  const quantidade = (curRes.data ?? []).reduce(
    (s, r) => s + (r.quantidade ?? 0),
    0,
  );
  const sumOrNull = (rows: Array<{ valor_total: number | null }> | null) => {
    const list = rows ?? [];
    return list.length > 0
      ? list.reduce((s, r) => s + (r.valor_total ?? 0), 0)
      : null;
  };

  return {
    lojaId,
    dataReferencia: refDate,
    valor,
    quantidade,
    valorSemanaAnterior: sumOrNull(weekRes.data),
    valorDiaAnterior: sumOrNull(dayRes.data),
  };
}

async function fetchLaggedSales(ctx: TvContext): Promise<LaggedSales[]> {
  const results = await Promise.all(ctx.linxLojaIds.map(fetchLaggedStore));
  return results.filter((r): r is LaggedSales => r !== null);
}

// ─────────────────────────────────────────────────────────────────────────────
// Bases de comparação Degust: ONTEM (principal v3) + mesmo dia da semana
// passada (secundário) — uma única query em degust_vendas_diarias
// ─────────────────────────────────────────────────────────────────────────────

interface DegustReferenceSales {
  /** R$ por loja ONTEM (base do delta principal, pró-rateada no uso). */
  yesterday: Map<number, number>;
  /** R$ por loja no MESMO DIA da semana passada (delta secundário). */
  lastWeek: Map<number, number>;
}

async function fetchDegustReference(ctx: TvContext): Promise<DegustReferenceSales> {
  const yesterday = new Map<number, number>();
  const lastWeek = new Map<number, number>();
  const ids = [...ctx.degustLojaIds];
  if (ids.length === 0) return { yesterday, lastWeek };
  // Referências relativas ao dia COMERCIAL (virada às 23h): "ontem" é o
  // dia recém-fechado, não o dia-calendário.
  const businessToday = parseIsoDateLocal(businessTodayIso(new Date()));
  const yesterdayDate = toIsoDateLocal(addDays(businessToday, -1));
  const lastWeekDate = toIsoDateLocal(addDays(businessToday, -7));
  // Paginado: degust_vendas_diarias é linha-por-produto (2 dias × N lojas
  // pode passar de 1000 — o PostgREST cortaria silenciosamente).
  const rows = await fetchAllPages((from, to) =>
    supabase
      .from('degust_vendas_diarias')
      .select('loja_id, valor_total, data')
      .in('data', [yesterdayDate, lastWeekDate])
      .in('loja_id', ids)
      .order('id')
      .range(from, to),
  );
  for (const row of rows) {
    const target = row.data === yesterdayDate ? yesterday : lastWeek;
    target.set(row.loja_id, (target.get(row.loja_id) ?? 0) + (row.valor_total ?? 0));
  }
  return { yesterday, lastWeek };
}

// ─────────────────────────────────────────────────────────────────────────────
// Metas (loja × dia da semana, convenção JS Date.getDay(): 0=domingo)
// ─────────────────────────────────────────────────────────────────────────────

async function fetchMetas(): Promise<Map<string, number>> {
  const { data, error } = await supabase
    .from('metas_vendas')
    .select('loja_id, dia_semana, valor_meta')
    .limit(1000);
  if (error) throw error;
  const out = new Map<string, number>();
  for (const row of data ?? []) {
    out.set(`${row.loja_id}:${row.dia_semana}`, row.valor_meta);
  }
  return out;
}

function metaFor(
  metas: Map<string, number> | undefined,
  lojaId: number,
  date: Date,
): number | null {
  if (!metas) return null;
  return metas.get(`${lojaId}:${date.getDay()}`) ?? null;
}

// ─────────────────────────────────────────────────────────────────────────────
// Estoque em alerta (JOIN com produtos ATIVOS — regra dura do projeto)
// ─────────────────────────────────────────────────────────────────────────────

/** Exportado para o `useTvStoreDetail` compartilhar a MESMA query/cache. */
export async function fetchStockAlerts(): Promise<StockRow[]> {
  // PostgREST não compara coluna×coluna (quantidade_atual < quantidade_minima):
  // buscamos as linhas com mínimo definido e filtramos no cliente (~1.4k linhas
  // candidatas hoje). Paginação obrigatória: o PostgREST corta em 1000 linhas
  // mesmo com `.limit()` maior — `.order('id')` garante páginas estáveis.
  //
  // `setor` vai junto no select: a regra do CTO 2026-06-05 (alertas SÓ do
  // setor TV_ALERT_SETOR = produtos vendáveis) é aplicada client-side com
  // normalização em `buildStockSummary` — a caixa/acento no banco é
  // inconsistente ("CÂMARA FRIA" vs "Câmara Fria"), então um `.eq` server-side
  // exato deixaria variantes legítimas de "Produtos" passarem/caírem errado.
  const data = await fetchAllPages((from, to) =>
    supabase
      .from('estoque')
      .select(
        'loja_id, quantidade_atual, quantidade_minima, produto_master:produtos_master!inner(nome, ativo, setor)',
      )
      .eq('produto_master.ativo', true)
      .gt('quantidade_minima', 0)
      .or('oculto.is.null,oculto.eq.false')
      .order('id')
      .range(from, to),
  );
  return data.map((row) => ({
    loja_id: row.loja_id,
    quantidade_atual: row.quantidade_atual,
    quantidade_minima: row.quantidade_minima,
    produtoNome: row.produto_master?.nome ?? '(sem nome)',
    setor: row.produto_master?.setor ?? null,
  }));
}

