// Hook principal
// ─────────────────────────────────────────────────────────────────────────────

/** Retorno do {@link useTvDashboardData}. */
export interface TvDashboardData {
  network: TvNetworkSummary | null;
  stores: TvStoreData[];
  factory: TvFactoryData | null;
  exceptions: TvExceptionsResult;
  freshness: TvFreshness;
  /** Período do filtro global aplicado a perdas/marketing/comparativos. */
  period: TvPeriod;
  /** Offset de navegação aplicado (≤ 0; 0 = ao vivo). */
  offset: number;
  /** true = modo ao vivo (offset 0, polling 60s); false = histórico estático. */
  isLive: boolean;
  /** Range corrente do filtro (para rótulos na UI). */
  range: TvDateRange;
  /** Range anterior equivalente usado nos comparativos. */
  previousRange: TvDateRange;
  /**
   * Acompanhamento do mês CORRENTE (R3+R4): MTD da rede, meta mensal,
   * % e projeção + semanas com metas redistribuídas. Independe do
   * período/offset selecionado (é sempre o mês de hoje). null enquanto
   * o MTD não carregou.
   */
  monthProgress: TvMonthProgress | null;
  /**
   * Quebra delivery×balcão (loja {@link TV_DELIVERY_SPLIT_LOJA_ID}) da
   * DATA EXIBIDA: hoje no live, o dia selecionado quando `offset < 0`.
   * null fora do período `today` ou sem cupom delivery no dia.
   */
  deliverySplitToday: TvDeliverySplit | null;
  /** Curvas horárias ontem+hoje das lojas Degust (vazio no modo passado). */
  hourlyCurves: TvHourlyCurve[];
  /** true enquanto o contexto (lojas/canais) ainda não carregou. */
  isLoading: boolean;
  /** true quando o contexto falhou (painel não consegue montar). */
  isError: boolean;
}

const EMPTY_MOVEMENT: TvMovementSummary = {
  entradas: 0,
  saidas: 0,
  ultimaBipagem: null,
};

const EMPTY_PERDAS_AGG: PerdasAggregate = { valor: 0, itens: 0 };

/** Monta o resumo de perdas de UMA unidade a partir dos agregados. */
function perdasSummaryFor(
  agg: PeriodedAggregates<PerdasByLoja> | undefined,
  lojaId: number,
): TvPerdasSummary {
  const cur = agg?.current.byLoja.get(lojaId) ?? EMPTY_PERDAS_AGG;
  const prev = agg?.previous.byLoja.get(lojaId);
  return {
    valor: cur.valor,
    itens: cur.itens,
    deltaPct: relativeDelta(cur.valor, prev?.valor ?? null),
  };
}

const EMPTY_MARKETING_AGG: MarketingAggregate = { valor: 0, acoes: 0 };

/** Monta o resumo de marketing de UMA unidade a partir dos agregados. */
function marketingSummaryFor(
  agg: PeriodedAggregates<MarketingByLoja> | undefined,
  lojaId: number,
): TvMarketingSummary {
  const cur = agg?.current.byLoja.get(lojaId) ?? EMPTY_MARKETING_AGG;
  const prev = agg?.previous.byLoja.get(lojaId);
  return {
    valor: cur.valor,
    acoes: cur.acoes,
    deltaPct: relativeDelta(cur.valor, prev?.valor ?? null),
  };
}

/**
 * Hook principal do painel TV. Paraleliza todas as fontes e devolve o
 * snapshot consolidado (`network`, `stores`, `factory`, `exceptions`,
 * `freshness`, `monthProgress`). Vendas live re-buscam a cada 60s; o
 * resto a cada 5min (com invalidação antecipada via {@link useTvRealtime}).
 *
 * @param period - Filtro global Hoje/Semana/Mês — muda perdas, compras e
 *   seus comparativos. No modo live, vendas dos cards são SEMPRE de hoje.
 * @param offset - Navegação no histórico (R2): 0 = ao vivo; −n = período
 *   COMPLETO n posições atrás (dia/semana/mês conforme `period`). Com
 *   `offset < 0` o polling de 60s e o flash são DESLIGADOS — vendas vêm do
 *   total oficial (ticket-medio) do range deslocado e os deltas comparam
 *   períodos completos (sem pró-rata).
 */
export function useTvDashboardData(
  period: TvPeriod = 'today',
  offset = 0,
): TvDashboardData {
  // "now" que AVANÇA (tick de minuto): staleness/RAG/pró-rata reclassificam
  // mesmo quando NENHUMA query devolve dado novo (outage total). Sem isso o
  // chip ficaria "✓ ao vivo" pra sempre com tudo fora do ar.
  const tick = useMinuteClock();

  // Offset positivo não existe (não há futuro a navegar) — clamp em 0.
  const clampedOffset = Math.min(0, Math.trunc(offset));
  const isLive = clampedOffset === 0;
  // Ranges calculados FORA do snapshot: entram em query keys e fetchers.
  // Memoizados no tick (que só muda na virada do minuto) para identidade
  // estável entre renders — o useMemo do snapshot depende deles.
  // No modo passado o "anterior equivalente" é o período COMPLETO
  // imediatamente antes (sem pró-rata); no live mantém a semântica v3.
  const range = useMemo(
    () => shiftedPeriodRange(period, clampedOffset, tick),
    [period, clampedOffset, tick],
  );
  const previousRange = useMemo(
    () =>
      isLive
        ? previousPeriodRange(period, tick)
        : shiftedPeriodRange(period, clampedOffset - 1, tick),
    [isLive, period, clampedOffset, tick],
  );

  const ctxQuery = useQuery({
    queryKey: tvDashboardKeys.context(),
    queryFn: fetchTvContext,
    staleTime: TV_QUERY_INTERVALS.slowMs,
    refetchInterval: TV_QUERY_INTERVALS.slowMs,
  });
  const ctx = ctxQuery.data;

  const liveQuery = useQuery({
    queryKey: tvDashboardKeys.liveSales(),
    queryFn: () => {
      if (!ctx) throw new Error('tv-dashboard: contexto ausente');
      return fetchLiveSales(ctx);
    },
    // Modo passado NÃO faz polling de 60s nem usa flash (R2)
    enabled: !!ctx && isLive,
    refetchInterval: TV_QUERY_INTERVALS.liveMs,
    staleTime: 30_000,
  });

  // Vendas oficiais do range deslocado (modo passado) — uma chamada cobre
  // o range exibido + o anterior equivalente (contíguos por construção).
  const rangeQuery = useQuery({
    queryKey: tvDashboardKeys.rangeSales(range, previousRange),
    queryFn: () => {
      if (!ctx) throw new Error('tv-dashboard: contexto ausente');
      return fetchRangeSales(ctx, previousRange.from, range.to);
    },
    enabled: !!ctx && !isLive,
    staleTime: TV_QUERY_INTERVALS.slowMs,
    refetchInterval: TV_QUERY_INTERVALS.slowMs,
  });

  const laggedQuery = useQuery({
    queryKey: tvDashboardKeys.laggedSales(),
    queryFn: () => {
      if (!ctx) throw new Error('tv-dashboard: contexto ausente');
      return fetchLaggedSales(ctx);
    },
    // historico_vendas (Linx) parou em abr/2026 — só faz sentido no live
    enabled: !!ctx && isLive,
    staleTime: TV_QUERY_INTERVALS.slowMs,
    refetchInterval: TV_QUERY_INTERVALS.slowMs,
  });

  const referenceQuery = useQuery({
    queryKey: tvDashboardKeys.referenceSales(),
    queryFn: () => {
      if (!ctx) throw new Error('tv-dashboard: contexto ausente');
      return fetchDegustReference(ctx);
    },
    enabled: !!ctx && isLive,
    staleTime: TV_QUERY_INTERVALS.slowMs,
    refetchInterval: TV_QUERY_INTERVALS.slowMs,
  });

  // Acumulado do mês corrente (R3) — independe do período/offset exibido.
  const mtdQuery = useQuery({
    queryKey: tvDashboardKeys.mtdSales(),
    queryFn: () => {
      if (!ctx) throw new Error('tv-dashboard: contexto ausente');
      return fetchMtdSales(ctx);
    },
    enabled: !!ctx,
    staleTime: TV_QUERY_INTERVALS.slowMs,
    refetchInterval: TV_QUERY_INTERVALS.slowMs,
  });

  // Curvas horárias ontem+hoje (R5) — só no live (base do delta vs ontem).
  const hourlyQuery = useQuery({
    queryKey: tvDashboardKeys.hourlyCurves(),
    queryFn: fetchHourlyCurves,
    enabled: !!ctx && isLive,
    staleTime: TV_QUERY_INTERVALS.slowMs,
    refetchInterval: TV_QUERY_INTERVALS.slowMs,
  });

  // Quebra delivery do dia exibido (R1) — apenas período "hoje" (live ou
  // dia passado); a quebra não se aplica a agregados de semana/mês.
  // No live o dia exibido é o COMERCIAL (após 23h o painel já virou).
  const deliveryDate = isLive ? businessTodayIso(tick) : range.to;
  const deliveryQuery = useQuery({
    queryKey: tvDashboardKeys.deliverySplit(deliveryDate),
    queryFn: () => fetchDeliverySplitDay(deliveryDate),
    enabled: !!ctx && period === 'today',
    staleTime: TV_QUERY_INTERVALS.slowMs,
    refetchInterval: TV_QUERY_INTERVALS.slowMs,
  });

  // Metas mensais do mês corrente (R4) — tolera tabela ausente ([]).
  const metasMensaisQuery = useQuery({
    queryKey: tvDashboardKeys.metasMensais(),
    queryFn: () => fetchMetasMensais(new Date()),
    staleTime: TV_QUERY_INTERVALS.slowMs,
    refetchInterval: TV_QUERY_INTERVALS.slowMs,
  });

  const perdasQuery = useQuery({
    queryKey: tvDashboardKeys.perdas(period, clampedOffset),
    queryFn: () => fetchPerdasAggregates(range, previousRange),
    staleTime: TV_QUERY_INTERVALS.slowMs,
    refetchInterval: TV_QUERY_INTERVALS.slowMs,
  });

  const marketingQuery = useQuery({
    queryKey: tvDashboardKeys.marketing(period, clampedOffset),
    queryFn: () => fetchMarketingAggregates(range, previousRange),
    staleTime: TV_QUERY_INTERVALS.slowMs,
    refetchInterval: TV_QUERY_INTERVALS.slowMs,
  });

  const feedQuery = useQuery({
    queryKey: tvDashboardKeys.movementFeed(),
    queryFn: fetchMovementFeed,
    staleTime: TV_QUERY_INTERVALS.slowMs,
    refetchInterval: TV_QUERY_INTERVALS.slowMs,
  });

  const metasQuery = useQuery({
    queryKey: tvDashboardKeys.metas(),
    queryFn: fetchMetas,
    staleTime: TV_QUERY_INTERVALS.slowMs,
    refetchInterval: TV_QUERY_INTERVALS.slowMs,
  });

  const stockQuery = useQuery({
    queryKey: tvDashboardKeys.stock(),
    queryFn: fetchStockAlerts,
    staleTime: TV_QUERY_INTERVALS.slowMs,
    refetchInterval: TV_QUERY_INTERVALS.slowMs,
  });

  const movementsQuery = useQuery({
    queryKey: tvDashboardKeys.movements(),
    queryFn: fetchMovementsToday,
    staleTime: TV_QUERY_INTERVALS.slowMs,
    refetchInterval: TV_QUERY_INTERVALS.slowMs,
  });

  const factoryQuery = useQuery({
    queryKey: tvDashboardKeys.factoryProduction(),
    queryFn: fetchFactoryProduction,
    staleTime: TV_QUERY_INTERVALS.slowMs,
    refetchInterval: TV_QUERY_INTERVALS.slowMs,
  });

  return useMemo<TvDashboardData>(() => {
    const now = tick;
    // Dia COMERCIAL exibido no live: às 23h o painel vira pro dia seguinte
    // (tudo zera); na madrugada (00–08h) o novo dia segue zerado e o caixa
    // fechado fica no histórico (◀).
    const todayIso = businessTodayIso(now);
    // true SOMENTE na faixa 23h–00h (dia comercial já é amanhã): % pró-rata
    // do novo dia não tem leitura honesta (fração da janela = 1) → null.
    const isAfterClose = todayIso !== toIsoDateLocal(now);

    const stockDetail: Map<number, StockDetail> = buildStockSummary(
      stockQuery.data ?? [],
    );
    const movements = movementsQuery.data ?? new Map<number, MovementAggregate>();
    const feedByLoja = feedQuery.data ?? new Map<number, TvRecentMove[]>();
    const flashByLoja = new Map<number, FlashRow>(
      (liveQuery.data?.flash ?? []).map((f) => [f.loja_id, f]),
    );
    // dailyByLoja: loja → data → total (3 dias, do ticket-medio API)
    const dailyByLoja: Map<number, Map<string, number>> =
      liveQuery.data?.dailyByLoja ?? new Map<number, Map<string, number>>();
    const laggedByLoja = new Map<number, LaggedSales>(
      (laggedQuery.data ?? []).map((l) => [l.lojaId, l]),
    );
    const lastWeekByLoja = referenceQuery.data?.lastWeek ?? new Map<number, number>();
    // yesterdayByLoja do degust_vendas_diarias — pode ter sync parcial;
    // preferir yesterdayFromApiByLoja quando disponível
    const yesterdayByLoja = referenceQuery.data?.yesterday ?? new Map<number, number>();
    const perdasAgg = perdasQuery.data;
    const marketingAgg = marketingQuery.data;
    const lojaNomeById = new Map<number, string>(
      (ctx?.lojas ?? []).map((l) => [l.id, l.nome]),
