            deltaOntem = relativeDelta(
              valorHoje,
              paceBase ?? proRataDayBase(prevDayTotal, now),
            );

            // deltaSemana: só quando period='week'
            if (period === 'week') {
              const weekAgoDate = toIsoDateLocal(
                addDays(parseIsoDateLocal(todayIso), -7),
              );
              const weekAgoTotal =
                dailyByLoja.get(loja.id)?.get(weekAgoDate) ??
                lastWeekByLoja.get(loja.id) ??
                null;
              // Mesmo princípio do deltaOntem: base intradiária SEMPRE
              // pró-rateada — sem fallback pro dia inteiro cru.
              deltaSemana = weekOverWeekDelta(
                valorHoje,
                proRataDayBase(weekAgoTotal, now),
              );
            }
          }
        } else {
          const lagged = laggedByLoja.get(loja.id);
          if (lagged) {
            vendas = {
              valor: lagged.valor,
              cupons: null,
              ticketMedio: null,
              dataReferencia: lagged.dataReferencia,
              isLive: false,
              caixaAberto: null,
              atualizadoEm: null,
            };
            // Meta do dia da semana do DIA DE REFERÊNCIA (já encerrado → sem pró-rata)
            const refDate = parseIsoDateLocal(lagged.dataReferencia);
            metaDia = metaFor(metasQuery.data, loja.id, refDate);
            pctMeta = pctOfFullDayTarget(lagged.valor, metaDia);
            // Canal defasado: dia COMPLETO vs dia COMPLETO — sem pró-rata.
            // Principal v3 = vs dia ANTERIOR ao de referência.
            deltaOntem = relativeDelta(lagged.valor, lagged.valorDiaAnterior);
            deltaSemana = weekOverWeekDelta(
              lagged.valor,
              lagged.valorSemanaAnterior,
            );
          }
        }

        // ── Meta SEMANAL da loja (sempre mês/semana CORRENTES, como o
        // monthProgress — independe de period/offset). Realizado por dia =
        // diário oficial do MTD (01→hoje) com HOJE sobrescrito pelo flash
        // live quando disponível (flash > daily oficial parcial). No modo
        // histórico (offset < 0) o flash está desligado — fica o diário
        // oficial disponível, incluindo o de hoje se existir.
        let weeklyGoal: TvStoreWeeklyGoal | null = null;
        const metaMensalLoja = metaMensalByLoja.get(loja.id);
        if (channel === 'degust-live' && metaMensalLoja != null) {
          const realizadoPorDia = new Map<string, number>(
            mtdDailyByLoja.get(loja.id) ?? [],
          );
          if (isLive) {
            const flash = flashByLoja.get(loja.id);
            if (flash) {
              // Só sobrescrever quando o flash é do dia COMERCIAL corrente:
              // após a virada (23h) e na madrugada ele mostra o fechamento
              // do dia anterior, cujo oficial já está no MTD.
              const flashTime = parseDegustFlashDateTime(
                flash.ultima_atualizacao,
                now,
              );
              const flashDate = flashTime ? toIsoDateLocal(flashTime) : todayIso;
              if (flashDate === todayIso) {
                realizadoPorDia.set(todayIso, flash.total_vendas);
              }
            }
          }
          // "Hoje" da semana corrente = dia COMERCIAL (após 23h a semana
          // exibida já é a do novo dia — coerente com o card zerado).
          weeklyGoal = currentWeekGoal(
            metaMensalLoja,
            realizadoPorDia,
            parseIsoDateLocal(todayIso),
          );
        }

        const rag = classifyStoreRag({
          stockOutCount: stock?.zerados ?? 0,
          stockLowCount: stock?.abaixoMinimo ?? 0,
          // pctMeta do modo passado é % de dia COMPLETO — não alimenta a
          // regra de "venda fraca pró-rata" (vale só pro live).
          pctMetaProRata: channel === 'degust-live' && isLive ? pctMeta : null,
          isLiveChannel: channel === 'degust-live' && isLive,
          lastMovementAt: movement.ultimaBipagem,
          now,
        });

        // R1: quebra delivery×balcão — SÓ na loja com delivery embutido no
        // PDV (BSB Shopping), SÓ no período "hoje" (live ou dia passado) e
        // SÓ quando as DATAS batem: split de um dia não pode quebrar venda
        // de outro (ex.: madrugada, quando o flash ainda é o fechamento de
        // ontem e dataReferencia ≠ dia do split).
        const deliverySplit =
          loja.id === TV_DELIVERY_SPLIT_LOJA_ID &&
          period === 'today' &&
          deliveryData != null &&
          vendas != null &&
          deliveryData.data === vendas.dataReferencia
            ? {
                delivery: deliveryData.totalDelivery,
                // total oficial − delivery, clampado: arredondamentos da
                // fonte não podem produzir balcão negativo
                balcao: Math.max(0, vendas.valor - deliveryData.totalDelivery),
              }
            : null;

        return {
          lojaId: loja.id,
          nome: loja.nome,
          channel,
          vendas,
          metaDia,
          pctMeta,
          deltaSemana,
          deltaOntem,
          estoque: {
            zerados: stock?.zerados ?? 0,
            abaixoMinimo: stock?.abaixoMinimo ?? 0,
          },
          movimentacao: movement,
          perdas: perdasSummaryFor(perdasAgg, loja.id),
          marketing: marketingSummaryFor(marketingAgg, loja.id),
          criticalItems: sortCriticalItems(stock?.itens ?? []),
          recentMoves: feedByLoja.get(loja.id) ?? [],
          rag: rag.status,
          ragReasons: rag.reasons,
          deliverySplit,
          weeklyGoal,
        };
      });

    // ── Card da fábrica ──
    let factory: TvFactoryData | null = null;
    if (ctx?.factoryLojaId != null) {
      const fid = ctx.factoryLojaId;
      const stock = stockDetail.get(fid);
      const movement = movements.get(fid) ?? EMPTY_MOVEMENT;
      const rag = classifyStoreRag({
        stockOutCount: stock?.zerados ?? 0,
        stockLowCount: stock?.abaixoMinimo ?? 0,
        pctMetaProRata: null,
        isLiveChannel: false,
        lastMovementAt: movement.ultimaBipagem,
        now,
        // Janela de PRODUÇÃO (06–18h, threshold 2h) — mesma do card visual
        hours: TV_FACTORY_HOURS,
        noMovementThresholdHours: FACTORY_NO_MOVEMENT_THRESHOLD_HOURS,
      });
      factory = {
        lojaId: fid,
        nome: lojaNomeById.get(fid) ?? 'Fábrica',
        producao: factoryQuery.data ?? null,
        expedicoes: movement,
        estoque: {
          zerados: stock?.zerados ?? 0,
          abaixoMinimo: stock?.abaixoMinimo ?? 0,
        },
        perdas: perdasSummaryFor(perdasAgg, fid),
        marketing: marketingSummaryFor(marketingAgg, fid),
        criticalItems: sortCriticalItems(stock?.itens ?? []),
        recentMoves: feedByLoja.get(fid) ?? [],
        rag: rag.status,
        ragReasons: rag.reasons,
      };
    }

    // ── Freshness ──
    // Classificada com `now` do tick de minuto: quando dataUpdatedAt para de
    // avançar (outage), a idade cresce e o chip escala pra âmbar mesmo sem
    // nenhum dado novo chegar. Os timestamps CRUS ficam expostos no retorno.
    // No modo passado a fonte de vendas é a query de range (estática,
    // ciclo de 5min) — o intervalo esperado acompanha pra não marcar
    // "stale" um dado histórico que não muda.
    const freshness: TvFreshness = buildFreshness(
      isLive ? liveQuery.dataUpdatedAt : rangeQuery.dataUpdatedAt,
      stockQuery.dataUpdatedAt,
      isLive
        ? TV_QUERY_INTERVALS
        : { liveMs: TV_QUERY_INTERVALS.slowMs, slowMs: TV_QUERY_INTERVALS.slowMs },
      now,
    );

    // ── Exceções (vermelho > âmbar, máx 7 + excedente) ──
    const allExceptions: TvException[] = buildStockExceptions(
      stockDetail,
      lojaNomeById,
    );
    // "Sem movimentação" derivada do DADO estruturado (última bipagem ×
    // janela), nunca por parsing de ragReasons — independe da cor do card
    // (aparece mesmo com card vermelho) e cobre também a fábrica.
    for (const store of stores) {
      const noMovement = buildNoMovementException({
        lojaId: store.lojaId,
        lojaNome: store.nome,
        lastMovementAt: store.movimentacao.ultimaBipagem,
        now,
      });
      if (noMovement) allExceptions.push(noMovement);
    }
    if (factory) {
      const noMovement = buildNoMovementException({
        lojaId: factory.lojaId,
        lojaNome: factory.nome,
        lastMovementAt: factory.expedicoes.ultimaBipagem,
        now,
        hours: TV_FACTORY_HOURS,
        thresholdHours: FACTORY_NO_MOVEMENT_THRESHOLD_HOURS,
      });
      if (noMovement) allExceptions.push(noMovement);
    }
    // Exceção de staleness só faz sentido AO VIVO (dado passado é estático)
    if (isLive && freshness.vendasLive.level !== 'fresh' && (ctx?.degustLojaIds.size ?? 0) > 0) {
      const liveUpdatedAt = freshness.vendasLive.updatedAt;
      allExceptions.push({
        id: 'stale-data:vendas-live',
        kind: 'stale-data',
        severity: 'amber',
        lojaId: null,
        lojaNome: null,
        message: liveUpdatedAt
          ? `Venda live sem atualização desde ${new Date(liveUpdatedAt).toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' })}`
          : 'Venda live ainda não carregou',
      });
    }
    const exceptions = sortAndLimitExceptions(allExceptions);

    // ── Hero (rede) ──
    // Live: lojas degust com dado (caixa aberto ou fechado recentemente —
    // a madrugada mostra o fechamento de ontem). Modo passado: lojas degust
    // com total oficial no range selecionado.
    const liveStores = stores.filter((s) => s.channel === 'degust-live' && s.vendas != null);
    const vendasHoje = liveStores.reduce((s, st) => s + (st.vendas?.valor ?? 0), 0);
    const totalCupons = liveStores.reduce((s, st) => s + (st.vendas?.cupons ?? 0), 0);
    const ticketMedioRede = totalCupons > 0 ? vendasHoje / totalCupons : null;
    // R$/hora: live = horas decorridas da janela de hoje; passado = janela
    // COMPLETA × nº de dias do range (períodos já encerrados). A duração
    // deriva de TV_BUSINESS_HOURS (8h–23h = 15h) — nunca hardcodar.
    const businessFraction = businessDayFraction(now);
    const horasDecorridas = isLive
      ? businessFraction * TV_BUSINESS_WINDOW_HOURS
      : TV_BUSINESS_WINDOW_HOURS * rangeDayCount(range);
    const valorPorHora = horasDecorridas > 0 && vendasHoje > 0
      ? vendasHoje / horasDecorridas
      : null;
    const vendasPorHora = horasDecorridas > 0 && totalCupons > 0
      ? totalCupons / horasDecorridas
      : null;
    const metasHoje = liveStores
      .map((s) => s.metaDia)
      .filter((m): m is number => m != null && m > 0);
    const metaDia = metasHoje.length > 0 ? metasHoje.reduce((a, b) => a + b, 0) : null;

    // Base do delta principal:
    // - live: soma por loja do dia ANTERIOR ao dia comercial corrente,
    //   PACEADA pela curva horária real (R5) — sem curva, fallback PRÓ-RATA
    //   linear da janela (NUNCA o dia inteiro cru: inflava a queda de
    //   manhã). Fora da janela o pró-rata é null pra todas as lojas → base
    //   0 → delta null (sem comparação inventada);
    // - passado: total oficial do período equivalente anterior COMPLETO.
    const prevNetworkDate = toIsoDateLocal(
      addDays(parseIsoDateLocal(todayIso), -1),
    );
    const prevNetworkBase = isLive
      ? liveStores.reduce((sum, st) => {
          const prevVal =
            dailyByLoja.get(st.lojaId)?.get(prevNetworkDate) ??
            yesterdayByLoja.get(st.lojaId) ??
            0;
          if (prevVal <= 0) return sum;
          const pace = hourlyPaceBase(
            prevVal,
            hourlyByKey.get(`${st.lojaId}:${prevNetworkDate}`),
            now,
          );
          return sum + (pace ?? proRataDayBase(prevVal, now) ?? 0);
        }, 0)
      : liveStores.reduce(
          (sum, st) =>
            sum + sumRange(rangeData?.dailyByLoja.get(st.lojaId), previousRange).total,
          0,
        );

    const networkWeekAgoDate = toIsoDateLocal(
      addDays(parseIsoDateLocal(todayIso), -7),
    );
    const lastWeekTotal = liveStores.reduce(
      (s, st) =>
        s +
        (dailyByLoja.get(st.lojaId)?.get(networkWeekAgoDate) ??
          lastWeekByLoja.get(st.lojaId) ??
          0),
      0,
    );
    const network: TvNetworkSummary | null = ctx
      ? {
          vendasHoje,
          ticketMedio: ticketMedioRede,
          valorPorHora,
          vendasPorHora,
          totalCupons,
          metaDia,
          // Live: pró-rata da janela (null após a virada das 23h — novo dia
          // ainda não abriu); passado dia: % do dia COMPLETO; passado
          // semana/mês: sem meta agregada honesta → null.
          pctMetaProRata: isLive
            ? isAfterClose
              ? null
              : pctOfProRataTarget(vendasHoje, metaDia, now)
            : period === 'today'
              ? pctOfFullDayTarget(vendasHoje, metaDia)
              : null,
          // deltaSemana: só no live com period='week' — base SEMPRE
          // pró-rateada (sem fallback pro dia inteiro cru).
          deltaSemana: isLive && period === 'week'
            ? weekOverWeekDelta(vendasHoje, proRataDayBase(lastWeekTotal, now))
            : null,
          // deltaOntem: live = vs dia anterior ao flash (base paceada);
          // passado = vs período equivalente anterior completo
          deltaOntem: relativeDelta(vendasHoje, prevNetworkBase || null),
          // Totais da REDE: incluem linhas sem loja_id (não atribuíveis a
          // nenhuma coluna — entram SOMENTE aqui).
          perdas: {
            valor: perdasAgg?.current.total.valor ?? 0,
            itens: perdasAgg?.current.total.itens ?? 0,
            deltaPct: relativeDelta(
              perdasAgg?.current.total.valor ?? 0,
              perdasAgg?.previous.total.valor ?? null,
            ),
          },
          marketing: {
            valor: marketingAgg?.current.total.valor ?? 0,
            acoes: marketingAgg?.current.total.acoes ?? 0,
            deltaPct: relativeDelta(
              marketingAgg?.current.total.valor ?? 0,
              marketingAgg?.previous.total.valor ?? null,
            ),
          },
          alertasCriticos: allExceptions.filter((e) => e.severity === 'red').length,
          lojasLive: liveStores.length,
          lojasDefasadas: stores.filter((s) => s.channel === 'linx-lagged').length,
        }
      : null;

    // ── Mês até agora (R3) + meta mensal com semanas redistribuídas (R4) ──
    // Sempre o mês CORRENTE, independente do período/offset exibido.
    let monthProgress: TvMonthProgress | null = null;
    const mtd = mtdQuery.data;
    if (mtd) {
      let mtdTotal = 0;
      for (const valor of mtd.byDate.values()) mtdTotal += valor;
      const metasMensais = metasMensaisQuery.data ?? [];
      const redeRow = metasMensais.find((m) => m.lojaId === null);
      const lojaRows = metasMensais.filter((m) => m.lojaId !== null);
      // Meta da rede: linha loja_id NULL; fallback = soma das metas por loja
      const metaMensal =
        redeRow != null
          ? redeRow.valorMeta
          : lojaRows.length > 0
            ? lojaRows.reduce((s, m) => s + m.valorMeta, 0)
            : null;
      const weeks =
        metaMensal != null && metaMensal > 0
          ? weeklyTargets(metaMensal, mtd.byDate, now)
          : [];
      monthProgress = {
        mtdTotal,
        metaMensal,
        pctMeta:
          metaMensal != null && metaMensal > 0
            ? (mtdTotal / metaMensal) * 100
            : null,
        projection: monthEndProjection(mtdTotal, now),
        weeks,
        currentWeek: weeks.find((w) => w.isCurrent) ?? null,
        mtdByLoja: mtd.byLoja,
      };
    }

    return {
      network,
      stores,
      factory,
      exceptions,
      freshness,
      period,
      offset: clampedOffset,
      isLive,
      range,
      previousRange,
      monthProgress,
      deliverySplitToday: deliveryData,
      hourlyCurves: hourlyQuery.data ?? [],
      isLoading: ctxQuery.isLoading,
      isError: ctxQuery.isError,
    };
  }, [
    // `tick` é o que faz staleness/RAG avançarem em outage total (sem ele a
    // classificação congelaria no último snapshot de dados).
    tick,
    period,
    clampedOffset,
    isLive,
    // Ranges memoizados no tick — identidade estável entre renders.
    range,
    previousRange,
    ctx,
    ctxQuery.isLoading,
    ctxQuery.isError,
    liveQuery.data,
    liveQuery.dataUpdatedAt,
    rangeQuery.data,
    rangeQuery.dataUpdatedAt,
    laggedQuery.data,
    referenceQuery.data,
    metasQuery.data,
    metasMensaisQuery.data,
    mtdQuery.data,
    hourlyQuery.data,
    deliveryQuery.data,
    stockQuery.data,
    stockQuery.dataUpdatedAt,
    movementsQuery.data,
    feedQuery.data,
    perdasQuery.data,
    marketingQuery.data,
    factoryQuery.data,
  ]);
}

