1	/**
2	 * @module features/tv-dashboard/model/types
3	 *
4	 * Tipos de domínio do Dashboard de Crise (painel TV `/tv`).
5	 * Spec: `.harness/spec/dashboard-tv-crise/spec.md`.
6	 */
7	
8	/**
9	 * Canal de origem do dado de venda de uma unidade.
10	 *
11	 * - `degust-live`: lojas integradas ao POS Degust (flash-vendas ao vivo).
12	 *   O conjunto de lojas vem da tabela `degust_stores` em runtime (hoje:
13	 *   Lago Sul, Águas Claras, BSB Shopping) — nunca hardcoded.
14	 * - `linx-lagged`: lojas no POS Linx sem integração live — usamos o último
15	 *   dia disponível em `historico_vendas` com selo "até DD/MM".
16	 * - `factory`: fábrica (sem venda; card de produção/expedição).
17	 */
18	export type TvSalesChannel = 'degust-live' | 'linx-lagged' | 'factory';
19	
20	/** Estado RAG (red/amber/green) de um card de unidade. */
21	export type TvRagStatus = 'ok' | 'amber' | 'red';
22	
23	/**
24	 * Filtro global de período do painel (v3): hoje / semana corrente
25	 * (segunda→hoje) / mês corrente (dia 1º→hoje). Perdas, compras e seus
26	 * comparativos respeitam o filtro; vendas dos cards são SEMPRE de hoje.
27	 */
28	export type TvPeriod = 'today' | 'week' | 'month';
29	
30	/** Range de dias FECHADO [from, to], ambos YYYY-MM-DD no fuso local. */
31	export interface TvDateRange {
32	  from: string;
33	  to: string;
34	}
35	
36	/** Severidade de um item de estoque crítico (zerado pesa mais). */
37	export type TvCriticalSeverity = 'zerado' | 'abaixo-minimo';
38	
39	/**
40	 * Item de estoque crítico NOMEADO de uma unidade, já ordenável por
41	 * severidade (zerados ⛔ primeiro; depois ⚠ por % faltante).
42	 */
43	export interface TvCriticalItem {
44	  nome: string;
45	  quantidade: number;
46	  minima: number;
47	  severity: TvCriticalSeverity;
48	}
49	
50	/** Linha do feed de movimentações nomeado ("AGORA" / drill-down). */
51	export interface TvRecentMove {
52	  /** Hora local HH:mm derivada de `data_movimentacao` ("—" se ausente). */
53	  hora: string;
54	  /** Timestamp cru ISO da movimentação (ordenar/tooltip), ou null. */
55	  timestamp: string | null;
56	  /** Tipo cru (`entrada` | `saida` | outros valores da tabela). */
57	  tipo: string;
58	  produtoNome: string;
59	  quantidade: number;
60	}
61	
62	/** Perdas agregadas (tabela `perdas`) no período do filtro global. */
63	export interface TvPerdasSummary {
64	  /** R$ somado de `valor_estimado` (linhas sem valor contam como 0). */
65	  valor: number;
66	  /** Número de registros de perda no período. */
67	  itens: number;
68	  /** Delta % vs período anterior equivalente (null sem base positiva). */
69	  deltaPct: number | null;
70	}
71	
72	/** Compras (NFs) agregadas — usado no drill-down por loja. */
73	export interface TvComprasSummary {
74	  valor: number;
75	  deltaPct: number | null;
76	}
77	
78	/** Marketing (ações de `acoes_marketing`) agregado no período do filtro global. */
79	export interface TvMarketingSummary {
80	  /** R$ somado de `valor_estimado` das ações de marketing. */
81	  valor: number;
82	  /** Número de ações de marketing no período. */
83	  acoes: number;
84	  /** Delta % vs período anterior equivalente (null sem base positiva). */
85	  deltaPct: number | null;
86	}
87	
88	/** Linha detalhada de perda (drill-down por loja). */
89	export interface TvPerdaDetail {
90	  id: number;
91	  produtoNome: string;
92	  quantidade: number;
93	  unidade: string | null;
94	  motivo: string;
95	  /** R$ estimado da perda (0 quando não informado). */
96	  valor: number;
97	  /** Timestamp ISO de `data_identificacao`, ou null. */
98	  data: string | null;
99	}
100	
101	/** Linha detalhada de NF de compra (drill-down por loja). */
102	export interface TvNotaFiscalDetail {
103	  id: number;
104	  numero: string;
105	  fornecedor: string;
106	  valor: number;
107	  /** Data de emissão `data_nota` (YYYY-MM-DD — campo canônico no app). */
108	  dataNota: string;
109	}
110	
111	/**
112	 * Quebra delivery×balcão de uma loja num dia (R1 da spec
113	 * `tv-acompanhamento-live`). Hoje só faz sentido para o BSB Shopping
114	 * (única loja cujo delivery entra junto no PDV — ver
115	 * `TV_DELIVERY_SPLIT_LOJA_ID` em tvMath).
116	 */
117	export interface TvDeliverySplit {
118	  lojaId: number;
119	  /** Dia a que a quebra se refere (YYYY-MM-DD). */
120	  data: string;
121	  /** R$ líquido somado dos cupons tipoVenda='2' (delivery) não cancelados. */
122	  totalDelivery: number;
123	  /** Número de cupons de delivery no dia. */
124	  cuponsDelivery: number;
125	}
126	
127	/**
128	 * Curva horária de vendas de uma loja num dia (movimentacao-produtos).
129	 * Usada como FRAÇÃO (cumulativo até a hora ÷ total) aplicada ao total
130	 * oficial — nunca como valor absoluto (kits têm valorUnitario 0).
131	 */
132	export interface TvHourlyCurve {
133	  lojaId: number;
134	  /** Dia da curva (YYYY-MM-DD). */
135	  data: string;
136	  /** R$ aproximado por hora cheia, chave "HH" com duas casas ("10".."22"). */
137	  byHour: Record<string, number>;
138	}
139	
140	/** Linha de `metas_mensais` normalizada (loja_id NULL = meta da rede). */
141	export interface TvMetaMensal {
142	  lojaId: number | null;
143	  ano: number;
144	  /** Mês 1-12 (convenção da tabela, NÃO o monthIndex0 do JS). */
145	  mes: number;
146	  valorMeta: number;
147	}
148	
149	/** Segmento seg-dom recortado ao mês (primeiro/último podem ter menos de 7 dias). */
150	export interface TvWeekSegment {
151	  /** 1-based ("Semana 1" do mês). */
152	  index: number;
153	  /** Primeiro dia do segmento (YYYY-MM-DD local). */
154	  from: string;
155	  /** Último dia do segmento (YYYY-MM-DD local). */
156	  to: string;
157	  /** Quantidade de dias do segmento (1-7). */
158	  days: number;
159	}
160	
161	/** Meta semanal recalculada de um segmento do mês (R4 da spec). */
162	export interface TvWeeklyGoal {
163	  segment: TvWeekSegment;
164	  /**
165	   * Meta da semana: redistribuição iterativa da meta mensal — semana que
166	   * não bate aumenta as seguintes; semana que supera reduz. Invariante:
167	   * realizado das semanas passadas + targets restantes = meta mensal.
168	   */
169	  target: number;
170	  /** Realizado no segmento (null para semanas futuras sem dados). */
171	  achieved: number | null;
172	  /** true quando o segmento contém o dia de hoje. */
173	  isCurrent: boolean;
174	}
175	
176	/**
177	 * Meta SEMANAL da loja (semana corrente seg-dom do mês CORRENTE), derivada
178	 * da meta mensal da loja em `metas_mensais` com a MESMA redistribuição de
179	 * {@link TvWeeklyGoal} (déficit/superávit das semanas passadas realoca os
180	 * targets restantes).
181	 */
182	export interface TvStoreWeeklyGoal {
183	  /** Meta da semana corrente (redistribuída — pode divergir do proporcional). */
184	  target: number;
185	  /** Realizado na semana corrente (segunda → agora, incluindo hoje live). */
186	  achieved: number;
187	  /** % da meta semanal (achieved/target × 100; null se target ≤ 0). */
188	  pct: number | null;
189	}
190	
191	/** Acompanhamento do mês corrente (R3+R4): MTD, meta mensal e semanas. */
192	export interface TvMonthProgress {
193	  /** Faturamento acumulado da rede no mês (01 → hoje, lojas Degust). */
194	  mtdTotal: number;
195	  /** Meta mensal da rede (linha loja_id NULL; fallback soma por loja). */
196	  metaMensal: number | null;
197	  /** % da meta mensal já realizada (null sem meta cadastrada). */
198	  pctMeta: number | null;
199	  /** Projeção de fim de mês por run-rate (mtd ÷ dias decorridos × dias do mês). */
200	  projection: number;
201	  /** Semanas do mês com metas redistribuídas (vazio sem meta cadastrada). */
202	  weeks: TvWeeklyGoal[];
203	  /** Semana corrente (null sem meta cadastrada ou fora do mês). */
204	  currentWeek: TvWeeklyGoal | null;
205	  /** MTD por loja (lojas Degust) — usado no relatório matinal. */
206	  mtdByLoja: Map<number, number>;
207	}
208	
209	/** Nível de frescor de um dado-fonte em relação ao intervalo esperado. */
210	export type TvFreshnessLevel = 'fresh' | 'stale' | 'very-stale';
211	
212	/** Severidade de uma exceção exibida na faixa inferior. */
213	export type TvExceptionSeverity = 'red' | 'amber';
214	
215	/** Tipo de exceção exibida na faixa inferior. */
216	export type TvExceptionKind =
217	  | 'stock-out'
218	  | 'stock-low'
219	  | 'no-movement'
220	  | 'stale-data';
221	
222	/** Janela de funcionamento usada no pró-rata da meta (hora local 0-24). */
223	export interface TvBusinessHours {
224	  start: number;
225	  end: number;
226	}
227	
228	/** Snapshot de vendas de uma unidade (live ou defasado). */
229	export interface TvSalesSnapshot {
230	  /** Valor vendido em R$ no dia de referência. */
231	  valor: number;
232	  /** Número de cupons/transações (null quando a fonte não informa). */
233	  cupons: number | null;
234	  /** Ticket médio em R$ (null quando a fonte não informa). */
235	  ticketMedio: number | null;
236	  /** Dia a que o dado se refere (YYYY-MM-DD). Para canal live = hoje. */
237	  dataReferencia: string;
238	  /** true quando o dado é ao vivo (flash-vendas); false = defasado. */
239	  isLive: boolean;
240	  /** Caixa aberto agora (apenas canal live; null quando não se aplica). */
241	  caixaAberto: boolean | null;
242	  /** Timestamp informado pela fonte da última atualização (ISO, ou null). */
243	  atualizadoEm: string | null;
244	}
245	
246	/** Contadores de alerta de estoque de uma unidade (apenas produtos ativos). */
247	export interface TvStockAlertSummary {
248	  /** Itens com quantidade ≤ 0 e mínimo definido (positivo). */
249	  zerados: number;
250	  /** Itens com quantidade entre 0 exclusivo e o mínimo. */
251	  abaixoMinimo: number;
252	}
253	
254	/** Item de estoque em alerta (detalhe usado na faixa de exceções). */
255	export interface TvStockAlertItem {
256	  produtoNome: string;
257	  quantidade: number;
258	  quantidadeMinima: number;
259	  /** true = zerado (vermelho); false = abaixo do mínimo (âmbar). */
260	  zerado: boolean;
261	}
262	
263	/** Heartbeat de movimentações de estoque de uma unidade no dia. */
264	export interface TvMovementSummary {
265	  /** Contagem de movimentações tipo `entrada` hoje. */
266	  entradas: number;
267	  /** Contagem de movimentações tipo `saida` hoje. */
268	  saidas: number;
269	  /** Timestamp ISO da última movimentação ("última bipagem"), ou null. */
270	  ultimaBipagem: string | null;
271	}
272	
273	/** Dados de um card de loja no grid. */
274	export interface TvStoreData {
275	  lojaId: number;
276	  nome: string;
277	  channel: TvSalesChannel;
278	  /** Vendas do dia de referência (null quando não há dado disponível). */
279	  vendas: TvSalesSnapshot | null;
280	  /** Meta do dia da semana de referência (`metas_vendas`), ou null. */
281	  metaDia: number | null;
282	  /**
283	   * % da meta. Canal live = pró-rata da janela de funcionamento;
284	   * canal defasado = % do dia COMPLETO de referência (dia já encerrado).
285	   * null quando não há meta cadastrada ou fora da janela.
286	   */
287	  pctMeta: number | null;
288	  /**
289	   * Delta % vs MESMO DIA da semana anterior — comparativo SECUNDÁRIO desde
290	   * a v3 (o principal é {@link deltaOntem}); a UI decide o que mostrar.
291	   */
292	  deltaSemana: number | null;
293	  /**
294	   * Delta % vs DIA ANTERIOR — comparativo PRINCIPAL (v3).
295	   * Canal live: hoje vs ontem com base PRÓ-RATEADA no mesmo ponto do dia.
296	   * Canal defasado: último dia vs dia anterior a ele (dias completos).
297	   */
298	  deltaOntem: number | null;
299	  estoque: TvStockAlertSummary;
300	  movimentacao: TvMovementSummary;
301	  /** Perdas da loja no PERÍODO do filtro global (+ delta vs anterior). */
302	  perdas: TvPerdasSummary;
303	  /** Marketing (ações `acoes_marketing`) da loja no PERÍODO (+ delta). */
304	  marketing: TvMarketingSummary;
305	  /**
306	   * Estoque crítico NOMEADO, ordenado por severidade (zerados primeiro,
307	   * depois abaixo do mínimo por % faltante). Lista completa — a coluna
308	   * exibe o top 5; o drill-down, tudo.
309	   */
310	  criticalItems: TvCriticalItem[];
311	  /** Mini-feed "AGORA": últimas movimentações de hoje (mais recente 1º). */
312	  recentMoves: TvRecentMove[];
313	  rag: TvRagStatus;
314	  /** Motivos legíveis (pt-BR) que levaram ao estado RAG. */
315	  ragReasons: string[];
316	  /**
317	   * Quebra "Loja R$X · Delivery R$Y" do dia exibido — preenchida SOMENTE
318	   * para a loja `TV_DELIVERY_SPLIT_LOJA_ID` (BSB Shopping) no período
319	   * `today` (live ou dia passado). `balcao` = total oficial − delivery,
320	   * clampado em ≥ 0. null/ausente nas demais lojas e períodos.
321	   */
322	  deliverySplit?: { delivery: number; balcao: number } | null;
323	  /**
324	   * Meta SEMANAL da loja (semana corrente do mês CORRENTE, independente do
325	   * período/offset exibido — mesma semântica do monthProgress). Target vem
326	   * da redistribuição da meta mensal da loja ({@link TvStoreWeeklyGoal});
327	   * `achieved` soma segunda → agora, com hoje = valor live do flash quando
328	   * disponível. null/ausente quando a loja não tem meta mensal cadastrada
329	   * no mês corrente ou não tem canal de venda com dado diário (Degust).
330	   */
331	  weeklyGoal?: { target: number; achieved: number; pct: number | null } | null;
332	}
333	
334	/** Produção agregada da fábrica num dia. */
335	export interface TvFactoryProduction {
336	  /** Dia a que a produção se refere (YYYY-MM-DD — último dia com registro). */
337	  dataReferencia: string;
338	  /** Quantidade de produtos distintos produzidos. */
339	  itens: number;
340	  /** Soma das quantidades produzidas. */
341	  totalUnidades: number;
342	}
343	
344	/** Dados do card diferenciado da fábrica. */
345	export interface TvFactoryData {
346	  lojaId: number;
347	  nome: string;
348	  /** Produção do dia (`daily_production` com loja_id NULL), ou null. */
349	  producao: TvFactoryProduction | null;
350	  /** Expedições = movimentações da fábrica hoje (saídas para lojas). */
351	  expedicoes: TvMovementSummary;
352	  estoque: TvStockAlertSummary;
353	  /** Perdas da fábrica no PERÍODO do filtro global (+ delta). */
354	  perdas: TvPerdasSummary;
355	  /** Marketing (ações `acoes_marketing` da fábrica) no PERÍODO (+ delta). */
356	  marketing: TvMarketingSummary;
357	  /** Estoque crítico nomeado da fábrica (mesma ordenação das lojas). */
358	  criticalItems: TvCriticalItem[];
359	  /** Mini-feed "AGORA" da fábrica (últimas movimentações de hoje). */
360	  recentMoves: TvRecentMove[];
361	  rag: TvRagStatus;
362	  ragReasons: string[];
363	}
364	
365	/** Uma linha da faixa de exceções. */
366	export interface TvException {
367	  /** Id estável para keys de render (ex.: `stock-out:4:BROWNIE`). */
368	  id: string;
369	  kind: TvExceptionKind;
370	  severity: TvExceptionSeverity;
371	  lojaId: number | null;
372	  lojaNome: string | null;
373	  /** Mensagem pronta para exibição (pt-BR). */
374	  message: string;
375	  produtoNome?: string;
376	  quantidade?: number;
377	  quantidadeMinima?: number;
378	}
379	
380	/** Faixa de exceções já ordenada (vermelho antes de âmbar) e limitada. */
381	export interface TvExceptionsResult {
382	  items: TvException[];
383	  /** Quantas exceções ficaram de fora do limite (para "+N itens"). */
384	  overflowCount: number;
385	  /** Total de exceções antes do corte. */
386	  totalCount: number;
387	}
388	
389	/** Resumo da rede para o hero. */
390	export interface TvNetworkSummary {
391	  /**
392	   * Vendas de HOJE em R$ — soma apenas das lojas cujo dado é de hoje
393	   * (canal live). Lojas defasadas NÃO entram para não misturar dias.
394	   */
395	  vendasHoje: number;
396	  /** Soma das metas do dia das lojas que contribuem em `vendasHoje`. */
397	  metaDia: number | null;
398	  /** % da meta pró-rata da rede (mesma regra do card de loja live). */
399	  pctMetaProRata: number | null;
400	  /**
401	   * Delta % vs mesmo dia da semana passada (lojas live) — SECUNDÁRIO
402	   * desde a v3 ({@link deltaOntem} é o principal), ou null.
403	   */
404	  deltaSemana: number | null;
405	  /**
406	   * Delta % vs ONTEM (lojas live, base pró-rateada no mesmo ponto do
407	   * dia) — comparativo PRINCIPAL da v3, ou null.
408	   */
409	  deltaOntem: number | null;
410	  /**
411	   * Perdas da REDE no período do filtro (toda a tabela `perdas`,
412	   * inclusive linhas sem loja_id — que não aparecem em nenhuma coluna).
413	   */
414	  perdas: TvPerdasSummary;
415	  /**
416	   * Marketing da REDE no período (ações `acoes_marketing` de todas as lojas).
417	   */
418	  marketing: TvMarketingSummary;
419	  /** Total de exceções vermelhas na rede (sem cap de exibição). */
420	  alertasCriticos: number;
421	  /** Ticket médio da rede (vendasHoje / totalCupons), ou null. */
422	  ticketMedio: number | null;
423	  /** R$ por hora decorrida na janela comercial (vendasHoje / horas desde abertura). */
424	  valorPorHora: number | null;
425	  /** Vendas (transações) por hora decorrida na janela comercial. */
426	  vendasPorHora: number | null;
427	  /** Total de cupons/transações da rede (soma das lojas live). */
428	  totalCupons: number;
429	  /** Quantidade de lojas com venda ao vivo. */
430	  lojasLive: number;
431	  /** Quantidade de lojas com dado defasado. */
432	  lojasDefasadas: number;
433	}
434	
435	/** Frescor de um dado-fonte. */
436	export interface TvSourceFreshness {
437	  /** Última atualização bem-sucedida (ISO), ou null se nunca carregou. */
438	  updatedAt: string | null;
439	  level: TvFreshnessLevel;
440	  /** Intervalo esperado de atualização (ms) usado na classificação. */
441	  expectedIntervalMs: number;
442	}
443	
444	/** Freshness consolidado dos dados exibidos na TV. */
445	export interface TvFreshness {
446	  /** Vendas live (polling 60s na edge `degust-pos-financial`). */
447	  vendasLive: TvSourceFreshness;
448	  /** Estoque/alertas (polling 5min + Realtime). */
449	  estoque: TvSourceFreshness;
450	  /** Momento em que o snapshot foi montado (ISO). */
451	  geradoEm: string;
452	}
