/**
 * @module features/tv-dashboard/model/types
 *
 * Tipos de domínio do Dashboard de Crise (painel TV `/tv`).
 * Spec: `.harness/spec/dashboard-tv-crise/spec.md`.
 */

/**
 * Canal de origem do dado de venda de uma unidade.
 *
 * - `degust-live`: lojas integradas ao POS Degust (flash-vendas ao vivo).
 *   O conjunto de lojas vem da tabela `degust_stores` em runtime (hoje:
 *   Lago Sul, Águas Claras, BSB Shopping) — nunca hardcoded.
 * - `linx-lagged`: lojas no POS Linx sem integração live — usamos o último
 *   dia disponível em `historico_vendas` com selo "até DD/MM".
 * - `factory`: fábrica (sem venda; card de produção/expedição).
 */
export type TvSalesChannel = 'degust-live' | 'linx-lagged' | 'factory';

/** Estado RAG (red/amber/green) de um card de unidade. */
export type TvRagStatus = 'ok' | 'amber' | 'red';

/**
 * Filtro global de período do painel (v3): hoje / semana corrente
 * (segunda→hoje) / mês corrente (dia 1º→hoje). Perdas, compras e seus
 * comparativos respeitam o filtro; vendas dos cards são SEMPRE de hoje.
 */
export type TvPeriod = 'today' | 'week' | 'month';

/** Range de dias FECHADO [from, to], ambos YYYY-MM-DD no fuso local. */
export interface TvDateRange {
  from: string;
  to: string;
}

/** Severidade de um item de estoque crítico (zerado pesa mais). */
export type TvCriticalSeverity = 'zerado' | 'abaixo-minimo';

/**
 * Item de estoque crítico NOMEADO de uma unidade, já ordenável por
 * severidade (zerados ⛔ primeiro; depois ⚠ por % faltante).
 */
export interface TvCriticalItem {
  nome: string;
  quantidade: number;
  minima: number;
  severity: TvCriticalSeverity;
}

/** Linha do feed de movimentações nomeado ("AGORA" / drill-down). */
export interface TvRecentMove {
  /** Hora local HH:mm derivada de `data_movimentacao` ("—" se ausente). */
  hora: string;
  /** Timestamp cru ISO da movimentação (ordenar/tooltip), ou null. */
  timestamp: string | null;
  /** Tipo cru (`entrada` | `saida` | outros valores da tabela). */
  tipo: string;
  produtoNome: string;
  quantidade: number;
}

/** Perdas agregadas (tabela `perdas`) no período do filtro global. */
export interface TvPerdasSummary {
  /** R$ somado de `valor_estimado` (linhas sem valor contam como 0). */
  valor: number;
  /** Número de registros de perda no período. */
  itens: number;
  /** Delta % vs período anterior equivalente (null sem base positiva). */
  deltaPct: number | null;
}

/** Compras (NFs) agregadas — usado no drill-down por loja. */
export interface TvComprasSummary {
  valor: number;
  deltaPct: number | null;
}

/** Marketing (ações de `acoes_marketing`) agregado no período do filtro global. */
export interface TvMarketingSummary {
  /** R$ somado de `valor_estimado` das ações de marketing. */
  valor: number;
  /** Número de ações de marketing no período. */
  acoes: number;
  /** Delta % vs período anterior equivalente (null sem base positiva). */
  deltaPct: number | null;
}

/** Linha detalhada de perda (drill-down por loja). */
export interface TvPerdaDetail {
  id: number;
  produtoNome: string;
  quantidade: number;
  unidade: string | null;
  motivo: string;
  /** R$ estimado da perda (0 quando não informado). */
  valor: number;
  /** Timestamp ISO de `data_identificacao`, ou null. */
  data: string | null;
}

/** Linha detalhada de NF de compra (drill-down por loja). */
export interface TvNotaFiscalDetail {
  id: number;
  numero: string;
  fornecedor: string;
  valor: number;
  /** Data de emissão `data_nota` (YYYY-MM-DD — campo canônico no app). */
  dataNota: string;
}

/**
 * Quebra delivery×balcão de uma loja num dia (R1 da spec
 * `tv-acompanhamento-live`). Hoje só faz sentido para o BSB Shopping
 * (única loja cujo delivery entra junto no PDV — ver
 * `TV_DELIVERY_SPLIT_LOJA_ID` em tvMath).
 */
export interface TvDeliverySplit {
  lojaId: number;
  /** Dia a que a quebra se refere (YYYY-MM-DD). */
  data: string;
  /** R$ líquido somado dos cupons tipoVenda='2' (delivery) não cancelados. */
  totalDelivery: number;
  /** Número de cupons de delivery no dia. */
  cuponsDelivery: number;
}

/**
 * Curva horária de vendas de uma loja num dia (movimentacao-produtos).
 * Usada como FRAÇÃO (cumulativo até a hora ÷ total) aplicada ao total
 * oficial — nunca como valor absoluto (kits têm valorUnitario 0).
 */
export interface TvHourlyCurve {
  lojaId: number;
  /** Dia da curva (YYYY-MM-DD). */
  data: string;
  /** R$ aproximado por hora cheia, chave "HH" com duas casas ("10".."22"). */
  byHour: Record<string, number>;
}

/** Linha de `metas_mensais` normalizada (loja_id NULL = meta da rede). */
export interface TvMetaMensal {
  lojaId: number | null;
  ano: number;
  /** Mês 1-12 (convenção da tabela, NÃO o monthIndex0 do JS). */
  mes: number;
  valorMeta: number;
}

/** Segmento seg-dom recortado ao mês (primeiro/último podem ter menos de 7 dias). */
export interface TvWeekSegment {
  /** 1-based ("Semana 1" do mês). */
  index: number;
  /** Primeiro dia do segmento (YYYY-MM-DD local). */
  from: string;
  /** Último dia do segmento (YYYY-MM-DD local). */
  to: string;
  /** Quantidade de dias do segmento (1-7). */
  days: number;
}

/** Meta semanal recalculada de um segmento do mês (R4 da spec). */
export interface TvWeeklyGoal {
  segment: TvWeekSegment;
  /**
   * Meta da semana: redistribuição iterativa da meta mensal — semana que
   * não bate aumenta as seguintes; semana que supera reduz. Invariante:
   * realizado das semanas passadas + targets restantes = meta mensal.
   */
  target: number;
  /** Realizado no segmento (null para semanas futuras sem dados). */
  achieved: number | null;
  /** true quando o segmento contém o dia de hoje. */
  isCurrent: boolean;
}

/**
 * Meta SEMANAL da loja (semana corrente seg-dom do mês CORRENTE), derivada
 * da meta mensal da loja em `metas_mensais` com a MESMA redistribuição de
 * {@link TvWeeklyGoal} (déficit/superávit das semanas passadas realoca os
 * targets restantes).
 */
export interface TvStoreWeeklyGoal {
  /** Meta da semana corrente (redistribuída — pode divergir do proporcional). */
  target: number;
  /** Realizado na semana corrente (segunda → agora, incluindo hoje live). */
  achieved: number;
  /** % da meta semanal (achieved/target × 100; null se target ≤ 0). */
  pct: number | null;
}

/** Acompanhamento do mês corrente (R3+R4): MTD, meta mensal e semanas. */
export interface TvMonthProgress {
  /** Faturamento acumulado da rede no mês (01 → hoje, lojas Degust). */
  mtdTotal: number;
  /** Meta mensal da rede (linha loja_id NULL; fallback soma por loja). */
  metaMensal: number | null;
  /** % da meta mensal já realizada (null sem meta cadastrada). */
  pctMeta: number | null;
  /** Projeção de fim de mês por run-rate (mtd ÷ dias decorridos × dias do mês). */
  projection: number;
  /** Semanas do mês com metas redistribuídas (vazio sem meta cadastrada). */
  weeks: TvWeeklyGoal[];
  /** Semana corrente (null sem meta cadastrada ou fora do mês). */
  currentWeek: TvWeeklyGoal | null;
  /** MTD por loja (lojas Degust) — usado no relatório matinal. */
  mtdByLoja: Map<number, number>;
}

/** Nível de frescor de um dado-fonte em relação ao intervalo esperado. */
export type TvFreshnessLevel = 'fresh' | 'stale' | 'very-stale';

/** Severidade de uma exceção exibida na faixa inferior. */
export type TvExceptionSeverity = 'red' | 'amber';

/** Tipo de exceção exibida na faixa inferior. */
export type TvExceptionKind =
  | 'stock-out'
  | 'stock-low'
  | 'no-movement'
  | 'stale-data';

/** Janela de funcionamento usada no pró-rata da meta (hora local 0-24). */
export interface TvBusinessHours {
  start: number;
  end: number;
}

/** Snapshot de vendas de uma unidade (live ou defasado). */
export interface TvSalesSnapshot {
  /** Valor vendido em R$ no dia de referência. */
  valor: number;
  /** Número de cupons/transações (null quando a fonte não informa). */
  cupons: number | null;
  /** Ticket médio em R$ (null quando a fonte não informa). */
  ticketMedio: number | null;
  /** Dia a que o dado se refere (YYYY-MM-DD). Para canal live = hoje. */
  dataReferencia: string;
  /** true quando o dado é ao vivo (flash-vendas); false = defasado. */
  isLive: boolean;
  /** Caixa aberto agora (apenas canal live; null quando não se aplica). */
  caixaAberto: boolean | null;
  /** Timestamp informado pela fonte da última atualização (ISO, ou null). */
  atualizadoEm: string | null;
}

/** Contadores de alerta de estoque de uma unidade (apenas produtos ativos). */
export interface TvStockAlertSummary {
  /** Itens com quantidade ≤ 0 e mínimo definido (positivo). */
  zerados: number;
  /** Itens com quantidade entre 0 exclusivo e o mínimo. */
  abaixoMinimo: number;
}

/** Item de estoque em alerta (detalhe usado na faixa de exceções). */
export interface TvStockAlertItem {
  produtoNome: string;
  quantidade: number;
  quantidadeMinima: number;
  /** true = zerado (vermelho); false = abaixo do mínimo (âmbar). */
  zerado: boolean;
}

/** Heartbeat de movimentações de estoque de uma unidade no dia. */
export interface TvMovementSummary {
  /** Contagem de movimentações tipo `entrada` hoje. */
  entradas: number;
  /** Contagem de movimentações tipo `saida` hoje. */
  saidas: number;
  /** Timestamp ISO da última movimentação ("última bipagem"), ou null. */
  ultimaBipagem: string | null;
}

/** Dados de um card de loja no grid. */
export interface TvStoreData {
  lojaId: number;
  nome: string;
  channel: TvSalesChannel;
  /** Vendas do dia de referência (null quando não há dado disponível). */
  vendas: TvSalesSnapshot | null;
  /** Meta do dia da semana de referência (`metas_vendas`), ou null. */
  metaDia: number | null;
  /**
   * % da meta. Canal live = pró-rata da janela de funcionamento;
   * canal defasado = % do dia COMPLETO de referência (dia já encerrado).
   * null quando não há meta cadastrada ou fora da janela.
   */
  pctMeta: number | null;
  /**
   * Delta % vs MESMO DIA da semana anterior — comparativo SECUNDÁRIO desde
   * a v3 (o principal é {@link deltaOntem}); a UI decide o que mostrar.
   */
  deltaSemana: number | null;
  /**
   * Delta % vs DIA ANTERIOR — comparativo PRINCIPAL (v3).
   * Canal live: hoje vs ontem com base PRÓ-RATEADA no mesmo ponto do dia.
   * Canal defasado: último dia vs dia anterior a ele (dias completos).
   */
  deltaOntem: number | null;
  estoque: TvStockAlertSummary;
  movimentacao: TvMovementSummary;
  /** Perdas da loja no PERÍODO do filtro global (+ delta vs anterior). */
  perdas: TvPerdasSummary;
  /** Marketing (ações `acoes_marketing`) da loja no PERÍODO (+ delta). */
  marketing: TvMarketingSummary;
  /**
   * Estoque crítico NOMEADO, ordenado por severidade (zerados primeiro,
   * depois abaixo do mínimo por % faltante). Lista completa — a coluna
   * exibe o top 5; o drill-down, tudo.
   */
  criticalItems: TvCriticalItem[];
  /** Mini-feed "AGORA": últimas movimentações de hoje (mais recente 1º). */
  recentMoves: TvRecentMove[];
  rag: TvRagStatus;
  /** Motivos legíveis (pt-BR) que levaram ao estado RAG. */
  ragReasons: string[];
  /**
   * Quebra "Loja R$X · Delivery R$Y" do dia exibido — preenchida SOMENTE
   * para a loja `TV_DELIVERY_SPLIT_LOJA_ID` (BSB Shopping) no período
   * `today` (live ou dia passado). `balcao` = total oficial − delivery,
   * clampado em ≥ 0. null/ausente nas demais lojas e períodos.
   */
  deliverySplit?: { delivery: number; balcao: number } | null;
  /**
   * Meta SEMANAL da loja (semana corrente do mês CORRENTE, independente do
   * período/offset exibido — mesma semântica do monthProgress). Target vem
   * da redistribuição da meta mensal da loja ({@link TvStoreWeeklyGoal});
   * `achieved` soma segunda → agora, com hoje = valor live do flash quando
   * disponível. null/ausente quando a loja não tem meta mensal cadastrada
   * no mês corrente ou não tem canal de venda com dado diário (Degust).
   */
  weeklyGoal?: { target: number; achieved: number; pct: number | null } | null;
}

/** Produção agregada da fábrica num dia. */
export interface TvFactoryProduction {
  /** Dia a que a produção se refere (YYYY-MM-DD — último dia com registro). */
  dataReferencia: string;
  /** Quantidade de produtos distintos produzidos. */
  itens: number;
  /** Soma das quantidades produzidas. */
  totalUnidades: number;
}

/** Dados do card diferenciado da fábrica. */
export interface TvFactoryData {
  lojaId: number;
  nome: string;
  /** Produção do dia (`daily_production` com loja_id NULL), ou null. */
  producao: TvFactoryProduction | null;
  /** Expedições = movimentações da fábrica hoje (saídas para lojas). */
  expedicoes: TvMovementSummary;
  estoque: TvStockAlertSummary;
  /** Perdas da fábrica no PERÍODO do filtro global (+ delta). */
  perdas: TvPerdasSummary;
  /** Marketing (ações `acoes_marketing` da fábrica) no PERÍODO (+ delta). */
  marketing: TvMarketingSummary;
  /** Estoque crítico nomeado da fábrica (mesma ordenação das lojas). */
  criticalItems: TvCriticalItem[];
  /** Mini-feed "AGORA" da fábrica (últimas movimentações de hoje). */
  recentMoves: TvRecentMove[];
  rag: TvRagStatus;
  ragReasons: string[];
}

/** Uma linha da faixa de exceções. */
export interface TvException {
  /** Id estável para keys de render (ex.: `stock-out:4:BROWNIE`). */
  id: string;
  kind: TvExceptionKind;
  severity: TvExceptionSeverity;
  lojaId: number | null;
  lojaNome: string | null;
  /** Mensagem pronta para exibição (pt-BR). */
  message: string;
  produtoNome?: string;
  quantidade?: number;
  quantidadeMinima?: number;
}

/** Faixa de exceções já ordenada (vermelho antes de âmbar) e limitada. */
export interface TvExceptionsResult {
  items: TvException[];
  /** Quantas exceções ficaram de fora do limite (para "+N itens"). */
  overflowCount: number;
  /** Total de exceções antes do corte. */
  totalCount: number;
}

/** Resumo da rede para o hero. */
export interface TvNetworkSummary {
  /**
   * Vendas de HOJE em R$ — soma apenas das lojas cujo dado é de hoje
   * (canal live). Lojas defasadas NÃO entram para não misturar dias.
   */
  vendasHoje: number;
  /** Soma das metas do dia das lojas que contribuem em `vendasHoje`. */
  metaDia: number | null;
  /** % da meta pró-rata da rede (mesma regra do card de loja live). */
  pctMetaProRata: number | null;
  /**
   * Delta % vs mesmo dia da semana passada (lojas live) — SECUNDÁRIO
   * desde a v3 ({@link deltaOntem} é o principal), ou null.
   */
  deltaSemana: number | null;
  /**
   * Delta % vs ONTEM (lojas live, base pró-rateada no mesmo ponto do
   * dia) — comparativo PRINCIPAL da v3, ou null.
   */
  deltaOntem: number | null;
  /**
   * Perdas da REDE no período do filtro (toda a tabela `perdas`,
   * inclusive linhas sem loja_id — que não aparecem em nenhuma coluna).
   */
  perdas: TvPerdasSummary;
  /**
   * Marketing da REDE no período (ações `acoes_marketing` de todas as lojas).
   */
  marketing: TvMarketingSummary;
  /** Total de exceções vermelhas na rede (sem cap de exibição). */
  alertasCriticos: number;
  /** Ticket médio da rede (vendasHoje / totalCupons), ou null. */
  ticketMedio: number | null;
  /** R$ por hora decorrida na janela comercial (vendasHoje / horas desde abertura). */
  valorPorHora: number | null;
  /** Vendas (transações) por hora decorrida na janela comercial. */
  vendasPorHora: number | null;
  /** Total de cupons/transações da rede (soma das lojas live). */
  totalCupons: number;
  /** Quantidade de lojas com venda ao vivo. */
  lojasLive: number;
  /** Quantidade de lojas com dado defasado. */
  lojasDefasadas: number;
}

/** Frescor de um dado-fonte. */
export interface TvSourceFreshness {
  /** Última atualização bem-sucedida (ISO), ou null se nunca carregou. */
  updatedAt: string | null;
  level: TvFreshnessLevel;
  /** Intervalo esperado de atualização (ms) usado na classificação. */
  expectedIntervalMs: number;
}

/** Freshness consolidado dos dados exibidos na TV. */
export interface TvFreshness {
  /** Vendas live (polling 60s na edge `degust-pos-financial`). */
  vendasLive: TvSourceFreshness;
  /** Estoque/alertas (polling 5min + Realtime). */
  estoque: TvSourceFreshness;
  /** Momento em que o snapshot foi montado (ISO). */
  geradoEm: string;
}

