/**
 * @module features/tv-dashboard/ui/TvStoreColumn
 *
 * Coluna vertical de loja — redesign baseado em research de TV dashboards
 * (Bach et al. IEEE TVCG 2023 + practitioner evidence):
 * - Número de vendas é o sinal primário → domina o espaço visualmente
 * - Máximo 5 elementos por card para não causar cognitive overload
 * - 1 RAG status por card (não 15 células coloridas)
 * - Detalhe de perdas/marketing/estoque → drill-down /tv/loja/:id
 */

import { useEffect, useRef, useState } from 'react';
import { Bike } from 'lucide-react';
import type { TvFreshnessLevel, TvPeriod, TvStoreData } from '../model/types';
import {
  expectedWeekFraction,
  parseBrDateTime,
  parseIsoDateLocal,
} from '../model/tvMath';
import { TvDeltaChip, TvLiveIndicator, TvMetaBar, TvRankChip, TvStateChip } from './TvChips';
import {
  TvColumnBipLine,
  TvColumnMetaBar,
  TvColumnStockLine,
  TvUnitColumn,
} from './TvColumnParts';
import {
  formatExactBRL,
  formatTicketBRL,
  formatWeekdayDayMonth,
  metaBarColorFromRatio,
  type TvBarColor,
} from './tvFormat';
import { useCountUp } from './useCountUp';

interface TvStoreColumnProps {
  store: TvStoreData;
  liveLevel: TvFreshnessLevel;
  period: TvPeriod;
  now: Date;
  rank?: number | null;
}

/** Coluna de loja — canal Degust live ou Linx defasado. */
export function TvStoreColumn({ store, liveLevel, period, now, rank }: TvStoreColumnProps) {
  const { vendas, channel } = store;
  const isLive = channel === 'degust-live';
  const valorAnim = useCountUp(vendas?.valor ?? 0);
  const refDate = vendas ? parseIsoDateLocal(vendas.dataReferencia) : null;

  // Flash dourado ao atualizar o valor de venda
  const prevValueRef = useRef(vendas?.valor);
  const [flashing, setFlashing] = useState(false);
  const flashKeyRef = useRef(0);
  useEffect(() => {
    if (
      vendas?.valor != null &&
      prevValueRef.current != null &&
      vendas.valor !== prevValueRef.current
    ) {
      flashKeyRef.current += 1;
      setFlashing(true);
      const t = window.setTimeout(() => setFlashing(false), 450);
      prevValueRef.current = vendas.valor;
      return () => window.clearTimeout(t);
    }
    prevValueRef.current = vendas?.valor;
  }, [vendas?.valor]);

  // Linha de status: fonte + horário de atualização
  const updateTime = isLive ? parseBrDateTime(vendas?.atualizadoEm) : null;
  const laggedLabel = !isLive && refDate ? formatWeekdayDayMonth(refDate) : null;

  const showRank = rank != null && rank >= 1 && rank <= 3;

  return (
    <TvUnitColumn lojaId={store.lojaId} nome={store.nome} rag={store.rag} testId="tv-store-column">

      {/* Header: nome + chips de status */}
      <div className="flex items-start justify-between gap-2">
        <h2 className="min-w-0 font-momma text-sm font-semibold leading-tight text-[#5F6F63] truncate">
          {store.nome.replace(/^Momma\s+/i, '')}
        </h2>
        <div className="flex shrink-0 items-center gap-1">
          {showRank && <TvRankChip rank={rank as 1 | 2 | 3} />}
          <TvStateChip rag={store.rag} />
        </div>
      </div>

      {/* Número de vendas + setinhas inline — exatamente como na v2 */}
      <div className="mt-2 flex flex-wrap items-end gap-x-2 gap-y-1">
        <span
          key={flashing ? `flash-${flashKeyRef.current}` : 'static'}
          className={`font-momma text-[clamp(1.375rem,1.9vw,2.5rem)] font-bold leading-none tabular-nums ${
            vendas ? 'text-[#2D362E]' : 'text-[#9ca3af]'
          }${flashing ? ' tv-value-flash' : ''}`}
          data-testid="tv-store-sales"
        >
          {/* CountUp anima o número bruto; o EXATO é formatado a cada frame */}
          {vendas ? formatExactBRL(valorAnim) : '—'}
        </span>
        {store.deltaOntem != null && (
          <TvDeltaChip delta={store.deltaOntem} label={isLive ? 'ontem' : 'dia ant.'} size="card" />
        )}
        {store.deltaSemana != null && period === 'week' && (
          <TvDeltaChip delta={store.deltaSemana} label="sem. ant." size="card" />
        )}
      </div>

      {/* R1: quebra Loja × Delivery (só BSB Shopping, período "hoje") —
          o número principal acima segue sendo o TOTAL oficial */}
      {store.deliverySplit && (
        <p
          className="mt-1 flex flex-wrap items-center gap-x-1.5 gap-y-0 text-xs tabular-nums text-[#7C887E]"
          data-testid="tv-delivery-split"
        >
          <span className="whitespace-nowrap">
            Loja{' '}
            <span className="font-medium text-[#5F6F63]">
              {formatExactBRL(store.deliverySplit.balcao)}
            </span>
          </span>
          <span aria-hidden>·</span>
          <span className="inline-flex items-center gap-1 whitespace-nowrap">
            <Bike className="h-3 w-3 shrink-0 text-[#57715B]" aria-hidden />
            Delivery{' '}
            <span className="font-medium text-[#5F6F63]">
              {formatExactBRL(store.deliverySplit.delivery)}
            </span>
          </span>
        </p>
      )}

      {/* Status de fonte — compacto, sem "ao vivo" como texto */}
      <p className="mt-1 flex items-center gap-1.5 text-xs text-[#9ca3af]">
        <TvLiveIndicator channel={channel} liveLevel={liveLevel} />
        {isLive
          ? updateTime
            ? `${updateTime.getHours().toString().padStart(2, '0')}:${updateTime.getMinutes().toString().padStart(2, '0')}`
            : 'hoje'
          : laggedLabel ?? 'sem dados'}
      </p>

      {/* Barra de meta do DIA */}
      <TvColumnMetaBar pctMetaProRata={store.pctMeta} metaDia={store.metaDia} now={now} />

      {/* Meta da SEMANA corrente (seg–dom) — linha secundária, não compete
          com o número grande de vendas do dia. Ausente quando a loja não
          tem meta mensal cadastrada (weeklyGoal null/undefined). */}
      {store.weeklyGoal && (
        <TvStoreWeeklyGoalLine weeklyGoal={store.weeklyGoal} now={now} />
      )}

      {/* Nº de vendas + R$/venda — cada parte non-breaking para não cortar */}
      {isLive && (vendas?.cupons != null || vendas?.ticketMedio != null) && (
        <div className="mt-2 flex flex-wrap items-baseline gap-x-1.5 gap-y-0 text-xs tabular-nums text-[#7C887E]">
          {vendas?.cupons != null && (
            <span className="whitespace-nowrap font-medium">
              {vendas.cupons} vendas
            </span>
          )}
          {vendas?.ticketMedio != null && vendas.ticketMedio > 0 && (
            <span className="whitespace-nowrap">
              {vendas.cupons != null && '· '}
              <span className="font-medium">{formatTicketBRL(vendas.ticketMedio)}</span>
              <span>/venda</span>
            </span>
          )}
        </div>
      )}

      {/* Bip + Status de estoque — 1 linha para cada */}
      <div className="mt-auto pt-3 space-y-1">
        <TvColumnBipLine ultimaBipagem={store.movimentacao.ultimaBipagem} now={now} />
        <TvColumnStockLine estoque={store.estoque} />
      </div>
    </TvUnitColumn>
  );
}

/** Cor do % da semana: emerald quando batida; senão mesma régua da barra. */
const WEEKLY_PCT_CLS: Record<TvBarColor, string> = {
  sage: 'text-[#57715B]',
  amber: 'text-amber-600',
  red: 'text-red-600',
};

/**
 * Linha SECUNDÁRIA de meta semanal do card: label "SEMANA" + % em destaque
 * (cor pace-adjusted pela mesma régua da diária/mensal; emerald quando
 * ≥ 100%) + valores exatos "R$ X / R$ Y" + mini barra de progresso
 * ({@link TvMetaBar} mini com tick dourado no esperado-agora da semana).
 *
 * COR pace-adjusted: ratio = %real / %esperado-agora, com esperado =
 * dias decorridos ÷ dias do segmento seg-dom corrente do mês
 * ({@link expectedWeekFraction} — derivado localmente porque o
 * `weeklyGoal` do model não expõe o segmento). Começo de semana no ritmo
 * NÃO fica vermelho. O % NUMÉRICO exibido segue sendo o real.
 */
function TvStoreWeeklyGoalLine({
  weeklyGoal,
  now,
}: {
  weeklyGoal: NonNullable<TvStoreData['weeklyGoal']>;
  now: Date;
}) {
  const { target, achieved, pct } = weeklyGoal;
  const beaten = pct != null && pct >= 100;
  const expectedWeekPct = Math.round(expectedWeekFraction(now) * 100);
  const barColor: TvBarColor = beaten
    ? 'sage'
    : metaBarColorFromRatio(
        pct != null && expectedWeekPct > 0 ? pct / expectedWeekPct : null,
        now,
      );
  const pctCls = beaten ? 'text-emerald-600' : WEEKLY_PCT_CLS[barColor];

  return (
    <div className="mt-2" data-testid="tv-weekly-goal">
      <div className="flex flex-wrap items-baseline justify-between gap-x-2 gap-y-0.5">
        <span className="font-momma text-[10px] font-semibold uppercase tracking-wider text-[#7C887E]">
          SEMANA
        </span>
        {/* Sem truncate: valor exato nunca pode ser cortado — quebra linha */}
        <span className="min-w-0 text-right font-momma text-[10px] tabular-nums text-[#9ca3af]">
          <span
            className={`text-xs font-bold tabular-nums ${pctCls}`}
            data-testid="tv-weekly-goal-pct"
          >
            {pct != null ? `${Math.round(pct)}%` : '—'}
          </span>{' '}
          {formatExactBRL(achieved)} / {formatExactBRL(target)}
        </span>
      </div>
      <div className="mt-1">
        <TvMetaBar
          fillPct={pct}
          expectedPct={pct != null ? expectedWeekPct : null}
          color={barColor}
          size="mini"
        />
      </div>
    </div>
  );
}

